var LIB=[{"g":"Email, documents and files","items":[{"id":"microsoft-365","name":"Microsoft 365","job":"Email, documents and files","k":"Software","w":"UK, EU or EEA","b":"Elsewhere","x":"Partial","o":false,"loc":"GB","locs":["GB","EU"],"hq":"US","co":"Microsoft Corporation (EU/UK contracts via Microsoft Ireland Operations Limited)","par":null,"parc":null,"store":"UK data centres for tenants signed up in the UK; EU data centres for tenants signed up in the EU. Covers Exchange mail, SharePoint, OneDrive, Teams chat and Copilot.","res":"yes-default","plans":"All commercial plans, including Business Basic and Business Standard, based on the country chosen at sign-up","mfa":"all plans","ai":"no","aid":"Microsoft states prompts, responses and data accessed through Microsoft Graph are not used to train foundation LLMs, including those used by Copilot. This applies to Copilot Chat included with business plans and paid Microsoft 365 Copilot.","np":"Microsoft 365 Business Basic grant for up to 300 users free, plus up to 75% off Business Standard and Business Premium. The free Business Premium grant ended from 1 July 2025.","note":"Your data stays in the UK or EU only if the tenant was set up with a UK or EU country, so check the data location in the admin centre. If you had the free Business Premium grant, check you moved users before it expired, or you risk losing data.","conf":"high","src":[["Overview of Product Terms Data Residency","https://learn.microsoft.com/en-us/microsoft-365/enterprise/m365-dr-product-terms-dr?view=o365-worldwide"],["Data Residency for Exchange Online","https://learn.microsoft.com/en-us/microsoft-365/enterprise/m365-dr-service-exo?view=o365-worldwide"],["Microsoft 365 data locations","https://learn.microsoft.com/en-us/microsoft-365/enterprise/o365-data-locations?view=o365-worldwide"],["Security defaults in Microsoft Entra ID","https://learn.microsoft.com/en-us/entra/fundamentals/security-defaults"],["Data, Privacy, and Security for Microsoft 365 Copilot","https://learn.microsoft.com/en-us/copilot/microsoft-365/microsoft-365-copilot-privacy"],["Export search results (Microsoft Purview eDiscovery)","https://learn.microsoft.com/en-us/purview/edisc-search-export"],["Microsoft for Nonprofits updates","https://learn.microsoft.com/en-us/industry/nonprofit/microsoft-for-nonprofits/updates"]]},{"id":"google-workspace","name":"Google Workspace","job":"Email, documents and files","k":"Software","w":"Elsewhere","b":"Elsewhere","x":"Yes","o":false,"loc":"","locs":[],"hq":"US","co":"Google LLC (EMEA customers usually contract with Google Cloud EMEA Limited, Ireland)","par":"Alphabet Inc.","parc":"US","store":"No location commitment by default. Business Standard and above can set a data region policy to Europe (EU); Business Starter and the free Nonprofits edition cannot. There is no UK-only region.","res":"yes-some-plans","plans":"Business Standard, Business Plus, Enterprise Standard and Plus (EU region via admin setting). Not Business Starter or the free Google Workspace for Nonprofits edition.","mfa":"all plans","ai":"no","aid":"Google states Workspace does not use customer data to train models without the customer's prior permission or instruction. The Privacy Hub refers to qualifying editions and does not list Business Starter or Nonprofits separately.","np":"Google Workspace for Nonprofits edition free; Business Standard about USD 3.50 per user per month and Business Plus about USD 6.16 (annual), through Google for Nonprofits.","note":"On the free Nonprofits edition or Business Starter you cannot choose where your data is stored. To keep data in Europe you need Business Standard or higher and must set the data region to Europe yourself.","conf":"high","src":[["Compare data region features across Google Workspace editions","https://knowledge.workspace.google.com/admin/compliance/compare-data-region-features-across-google-workspace-editions"],["Choose a geographic location for your data","https://knowledge.workspace.google.com/admin/compliance/choose-a-geographic-location-for-your-data"],["Google Workspace Offers for Nonprofits","https://www.google.com/nonprofits/workspace/compare/"],["Generative AI in Google Workspace Privacy Hub","https://knowledge.workspace.google.com/admin/generative-ai/generative-ai-in-google-workspace-privacy-hub"],["Export all your organization's data","https://knowledge.workspace.google.com/admin/migrate/export-all-your-organizations-data"],["Protect your business with 2-Step Verification","https://knowledge.workspace.google.com/admin/security/protect-your-business-with-2-step-verification"]]},{"id":"dropbox","name":"Dropbox","job":"Shared files","k":"Software","w":"Elsewhere","b":"Elsewhere","x":"Yes","o":false,"loc":"US","locs":["US"],"hq":"US","co":"Dropbox, Inc. (outside North America: Dropbox International Unlimited Company, Ireland)","par":null,"parc":null,"store":"US data centres by default. Teams can ask to move data to the UK or EU if they meet conditions.","res":"yes-on-request","plans":"Standard, Advanced, Business, Business Plus or Enterprise teams with at least 10 licences on annual billing; requests reviewed individually","mfa":"all plans","ai":"no","aid":"Dropbox says it will not build generative AI models using customer content without consent. Dash uses OpenAI for web search, on by default in chats, and says data sent is not used to train OpenAI models.","np":"40% off Business Standard and Advanced through TechSoup (announced 2020). Current availability for UK charities not confirmed.","note":"Your files are stored in the US unless your team has at least 10 licences on annual billing and asks Dropbox to move them. Small teams should assume US storage.","conf":"high","src":[["Where is my Dropbox data stored?","https://help.dropbox.com/security/physical-location-data-storage"],["EU Data Act Information","https://help.dropbox.com/security/eu-data-act-information"],["Dropbox AI Principles","https://www.dropbox.com/ai-principles"],["How to search and explore your content with Dropbox Dash","https://help.dropbox.com/view-edit/dropbox-ai-how-to"],["Dropbox plans comparison","https://www.dropbox.com/business/plans-comparison"],["How to require multi-factor authentication for Dropbox teams","https://help.dropbox.com/security/two-step-verification"],["Introducing Dropbox for Nonprofits","https://blog.techsoup.org/en-us/posts/introducing-dropbox-for-nonprofits"]]},{"id":"ionos-nextcloud-workspace","name":"IONOS Nextcloud Workspace","job":"Email, documents and files","k":"Software","w":"UK, EU or EEA","b":"UK or Europe","x":"Yes","o":true,"loc":"DE","locs":["DE"],"hq":"DE","co":"IONOS SE (UK customers contract with IONOS Cloud UK Limited)","par":"United Internet AG","parc":"DE","store":"IONOS data centres in Germany","res":"yes-default","plans":"All plans","mfa":"all plans","ai":"no","aid":"The AI assistant runs on the IONOS AI Model Hub. IONOS says it contractually guarantees company data will never be used to train public AI models.","np":null,"note":"Your data is held in Germany and the software is open source, so you can move to another Nextcloud host. The UK contract is with IONOS Cloud UK Limited, so check which entity is on your agreement.","conf":"medium","src":[["Nextcloud Workspace (IONOS UK)","https://www.ionos.co.uk/office-solutions/nextcloud-workspace"],["Nextcloud Workspace - Overview (IONOS docs)","https://docs.ionos.com/cloud/sovereign-workplace/nextcloud-workspace"],["Nextcloud Workspace for Business","https://cloud.ionos.co.uk/sovereign-workplace/nextcloud"],["A sovereign Microsoft 365 alternative: Nextcloud and IONOS join forces","https://nextcloud.com/blog/nextcloud-workspace-microsoft-365-alternative-by-nextcloud-and-ionos/"]]},{"id":"hetzner-storage-share","name":"Hetzner Storage Share","job":"Shared files","k":"Software","w":"UK, EU or EEA","b":"UK or Europe","x":"Yes","o":true,"loc":"DE","locs":["DE"],"hq":"DE","co":"Hetzner Online GmbH","par":null,"parc":null,"store":"Hetzner's own data centre in Falkenstein, Germany. No other location offered.","res":"yes-default","plans":"All plans (NX11, NX21, NX31)","mfa":"unclear","ai":"not-applicable","aid":"Hetzner's Storage Share pages advertise no AI features. Any AI apps would be ones you install yourself from the Nextcloud app store.","np":null,"note":"Files are stored in Germany and are not encrypted by default. Hetzner's docs do not mention two-factor login, so check you can switch it on for every user.","conf":"medium","src":[["Storage Share product page","https://www.hetzner.com/storage/storage-share/"],["Which storage is right for me? (Hetzner Docs)","https://docs.hetzner.com/storage/general/which-storage-is-right-for-me/"],["Security - Storage Share FAQ","https://docs.hetzner.com/storage/storage-share/faq/security/"]]},{"id":"mailbox-org","name":"mailbox.org","job":"Email and calendar","k":"Software","w":"UK, EU or EEA","b":"UK or Europe","x":"Yes","o":false,"loc":"DE","locs":["DE"],"hq":"DE","co":"Heinlein Hosting GmbH (mailbox)","par":"Heinlein Group","parc":"DE","store":"Own servers in data centres in Berlin, Germany","res":"yes-default","plans":"All plans","mfa":"all plans","ai":"not-applicable","aid":"No AI features are listed on the plans or product pages checked.","np":null,"note":"Mail, calendars and files are stored in Berlin and use open standards, so moving out is straightforward. The service rebranded from mailbox.org to mailbox in September 2025, so look for either name on invoices.","conf":"medium","src":[["Why mailbox","https://mailbox.org/en/why-mailbox/"],["Email hosting for businesses","https://mailbox.org/en/business/"],["Secure email service","https://mailbox.org/en/product/mail/"],["Setting up two-factor authentication in mailbox","https://kb.mailbox.org/en/private/security-and-privacy/how-to-use-two-factor-authentication-2fa/"],["Our price plans","https://mailbox.org/en/prices/"],["Mailbox (company) - Wikipedia","https://en.wikipedia.org/wiki/Mailbox_(company)"]]},{"id":"proton","name":"Proton","job":"Encrypted email and files","k":"Software","w":"Elsewhere","b":"UK or Europe","x":"Partial","o":false,"loc":"CH","locs":["CH"],"hq":"CH","co":"Proton AG","par":"Proton Foundation","parc":"CH","store":"Switzerland primarily. Proton says business data is on servers in Europe under Swiss law. Some infrastructure has been moved to Germany and Norway since 2024 to 2025, but no customer choice of location is stated.","res":"unclear","plans":null,"mfa":"all plans","ai":"no","aid":"Proton says Proton Scribe does not use content data to train its models, and Lumo keeps no server-side logs and uses zero-access encryption. Scribe is an add-on; Lumo is included in Workspace Premium.","np":"Discount for registered nonprofits on business plans, amount agreed with sales on request.","note":"Data is mainly held in Switzerland, which is outside the UK and EU but has UK and EU adequacy decisions. Most content is end-to-end encrypted, so if you lose your password and recovery details, the data cannot be recovered.","conf":"medium","src":[["Proton for Business FAQ","https://proton.me/business/faq"],["Proton Privacy Policy","https://proton.me/legal/privacy"],["Proton AG - Wikipedia","https://en.wikipedia.org/wiki/Proton_AG"],["Proton to Expand Infrastructure Beyond Switzerland Over Surveillance Law","https://cyberinsider.com/proton-confirms-gradual-exit-from-switzerland-over-surveillance-law-fears/"],["Proton Mail Export Tool","https://proton.me/support/proton-mail-export-tool"],["Two-factor authentication (2FA)","https://proton.me/support/two-factor-authentication-2fa"],["Nonprofit discount","https://proton.me/business/nonprofit-discount"],["Business suite plans and pricing","https://proton.me/business/plans"]]},{"id":"infomaniak-ksuite","name":"Infomaniak kSuite","job":"Email, documents and files","k":"Software","w":"Elsewhere","b":"UK or Europe","x":"Don't know","o":false,"loc":"CH","locs":["CH"],"hq":"CH","co":"Infomaniak Network SA","par":null,"parc":null,"store":"Infomaniak's own data centres in Switzerland","res":"no","plans":null,"mfa":"some plans","ai":"no","aid":"Infomaniak says data sent to its Euria assistant is neither saved nor used to train AI, and processing stays in its Swiss data centres. Euria runs on open source models.","np":null,"note":"Your data is held in Switzerland, which is outside the UK and EU but has UK and EU adequacy decisions. Two-step login is not available on the free tier, so use a paid plan for staff accounts.","conf":"medium","src":[["kSuite","https://www.infomaniak.com/en/ksuite"],["kSuite prices","https://www.infomaniak.com/en/ksuite/ksuite-pro/prices"],["Euria: the free, sovereign AI assistant","https://news.infomaniak.com/en/euria-sovereign-ai-assistant/"],["Euria, the sovereign AI assistant","https://www.infomaniak.com/en/euria"],["Nonprofits: Why and How to Migrate to Infomaniak","https://infoswitch.fr/en/blog/nonprofits-migrate-infomaniak"]]},{"id":"tuta","name":"Tuta","job":"Encrypted email and calendar","k":"Software","w":"UK, EU or EEA","b":"UK or Europe","x":"Partial","o":false,"loc":"DE","locs":["DE"],"hq":"DE","co":"Tutao GmbH","par":null,"parc":null,"store":"Tuta's own servers in ISO 27001 certified data centres in Germany","res":"yes-default","plans":"All plans","mfa":"all plans","ai":"not-applicable","aid":"No AI features are listed on the business or security pages checked.","np":"50% off for registered nonprofits and schools, by emailing sales with proof of status.","note":"Data is stored in Germany and is end-to-end encrypted. You cannot connect ordinary email apps over IMAP, so exporting mail means using Tuta's desktop app.","conf":"medium","src":[["Security at Tuta","https://tuta.com/security"],["Secure Business Emails","https://tuta.com/business"],["Good causes deserve support","https://tuta.com/discount"],["End-to-End Encrypted Cloud Storage","https://tuta.com/drive"],["We've just added single-click email export to the free Tuta desktop email clients","https://discuss.privacyguides.net/t/we-ve-just-added-single-click-email-export-to-the-free-tuta-desktop-email-clients/24749"]]}]},{"g":"Talking and meeting","items":[{"id":"zoom","name":"Zoom","job":"Video meetings","k":"Software","w":"Elsewhere","b":"Elsewhere","x":"Partial","o":false,"loc":"US","locs":["US"],"hq":"US","co":"Zoom Communications, Inc.","par":null,"parc":null,"store":"Plan assumed: Zoom Workplace Pro. Recordings, transcripts and other customer content are stored in the US by default. Admins on paid plans, including Pro, can move recordings, transcripts, in-meeting chat and whiteboards to Germany, but account and operational data stay in the US.","res":"yes-some-plans","plans":"Paid plans including Pro can set the storage region to Germany for recordings, transcripts, in-meeting chat and whiteboard content. Zoom's fuller EU infrastructure is described for EU Education and Enterprise customers. No UK storage region is listed.","mfa":"all plans","ai":"no","aid":"Zoom's terms (section 10.2) say it does not use audio, video, chat, screen sharing, attachments or other communications-like content to train Zoom or third-party AI models. This applies to all plans; no opt-out is needed.","np":"50% off Zoom Workplace Pro and Business, the Large Meeting add-on and Zoom Webinar for verified nonprofits with budgets under US$10 million, verified through Goodstack. No longer offered through TechSoup.","note":"Recordings are stored in the US unless an admin changes the data storage location to Germany in account settings. Account data stays in the US either way.","conf":"high","src":[["Managing Data & Storage location","https://support.zoom.com/hc/en/article?id=zm_kb&sysparm_article=KB0066473"],["European Union's General Data Protection Regulation (GDPR) | Zoom Trust Center","https://www.zoom.com/en/trust/gdpr/"],["Zoom EU Infrastructure Fact Sheet","https://media.zoom.com/download/assets/zoom-eu-infrastructure-fact-sheet.pdf/3d23251255a811f0bc811651fbd1a193?page=6&onlycontent=1&lang=null"],["Zoom Terms of Service","https://www.zoom.com/en/trust/terms/"],["Cloud recording - Zoom Developer Docs","https://developers.zoom.us/docs/build/cloud-recording/"],["Zoom adds two-factor authentication (2FA) support to all accounts - BleepingComputer","https://www.bleepingcomputer.com/news/security/zoom-adds-two-factor-authentication-2fa-support-to-all-accounts/"],["Secure Your Zoom Account with Two-Factor Authentication","https://www.zoom.com/en/blog/secure-your-zoom-account-with-two-factor-authentication/"],["Subscribing to Zoom as a nonprofit organization","https://support.zoom.com/hc/en/article?id=zm_kb&sysparm_article=KB0080298"],["How do I access Zoom for Nonprofits? (TechSoup)","https://support.techsoup.org/hc/en-us/articles/36503175618203-How-do-I-access-Zoom-for-Nonprofits-I-am-not-seeing-it-on-TechSoup"]]},{"id":"microsoft-teams","name":"Microsoft Teams","job":"Chat and video meetings","k":"Software","w":"UK, EU or EEA","b":"Elsewhere","x":"Partial","o":false,"loc":"GB","locs":["GB","EU"],"hq":"US","co":"Microsoft Corporation","par":null,"parc":null,"store":"Plan assumed: Microsoft 365 Business Basic (nonprofit grant) or Business Standard. For a tenant whose default geography is the UK, Teams chats are stored at rest in the UK under Microsoft's Product Terms. EU tenants get EU storage. Meeting recordings are saved to the recorder's OneDrive, which follows the same data residency rules.","res":"yes-default","plans":"All commercial Microsoft 365 plans that include Teams, based on the tenant's default geography (UK or EU). Advanced Data Residency is a paid add-on for stronger commitments.","mfa":"all plans","ai":"no","aid":"Microsoft states that prompts, responses and data accessed through Microsoft Graph are not used to train foundation large language models, including those used by Copilot. Optional feedback may be used to improve the service.","np":"Microsoft 365 Business Basic grant for up to 300 users, and up to 75% off Business Standard and Business Premium. The free Business Premium and Office 365 E1 grants ended for new grants on 1 July 2025.","note":"For UK tenants, Teams chats are stored in the UK. Recordings are saved in the OneDrive of the person who pressed record, so check where they end up when that person leaves.","conf":"high","src":[["Data Residency for Microsoft Teams","https://learn.microsoft.com/en-us/microsoft-365/enterprise/m365-dr-service-teams?view=o365-worldwide"],["Overview of Product Terms Data Residency","https://learn.microsoft.com/en-us/microsoft-365/enterprise/m365-dr-product-terms-dr?view=o365-worldwide"],["Export content with the Microsoft Teams Export APIs","https://learn.microsoft.com/en-us/microsoftteams/export-teams-content"],["Finding content in Microsoft Teams in eDiscovery","https://learn.microsoft.com/en-us/purview/edisc-search-teams"],["Security defaults in Microsoft Entra ID","https://learn.microsoft.com/en-us/entra/fundamentals/security-defaults"],["Data, Privacy, and Security for Microsoft 365 Copilot","https://learn.microsoft.com/en-us/copilot/microsoft-365/microsoft-365-copilot-privacy"],["Microsoft for Nonprofits updates","https://learn.microsoft.com/en-us/industry/nonprofit/microsoft-for-nonprofits/updates"]]},{"id":"slack","name":"Slack","job":"Team chat","k":"Software","w":"Elsewhere","b":"Elsewhere","x":"Partial","o":false,"loc":"US","locs":["US"],"hq":"US","co":"Slack Technologies, LLC","par":"Salesforce, Inc.","parc":"US","store":"Plan assumed: Pro (free for nonprofits with up to 250 members). Data is stored in the US. Business+ and Enterprise plans can choose data residency in London, Frankfurt, Paris, Stockholm or Zurich, but member profiles, membership details and analytics stay outside the chosen region.","res":"yes-some-plans","plans":"Business+ and Enterprise (London, Frankfurt, Paris, Stockholm, Zurich). Not available on Free or Pro.","mfa":"all plans","ai":"yes","aid":"Slack analyses customer data (messages, content, files) to train non-generative global models, such as emoji and channel recommendations, on all plans by default. Workspace owners can opt out by emailing feedback@slack.com with the subject 'Slack Global model opt-out request'. Slack says it does not train generative AI models on customer data without opt-in consent.","np":"Free Pro plan for workspaces with 250 or fewer members, 85% off Pro above that, and 85% off Business+. Eligibility checked through TechSoup.","note":"On Pro, messages are stored in the US and private channels and DMs cannot be exported. Slack uses your data for its recommendation models unless an owner emails feedback@slack.com to opt out.","conf":"high","src":[["Data residency for Slack","https://slack.com/help/articles/360035633934-Data-residency-for-Slack"],["Export your workspace data","https://slack.com/help/articles/201658943-Export-your-workspace-data"],["Set up two-factor authentication","https://slack.com/help/articles/204509068-Set-up-two-factor-authentication"],["Privacy principles: search, learning and artificial intelligence","https://slack.com/trust/data-management/privacy-principles"],["Apply for the Slack for Nonprofits discount","https://slack.com/help/articles/204368833-Apply-for-the-Slack-for-Nonprofits-discount"],["Slack Main Services Agreement","https://slack.com/main-services-agreement"]]},{"id":"whatsapp","name":"WhatsApp (work groups)","job":"Group messaging","k":"Software","w":"Elsewhere","b":"Elsewhere","x":"Partial","o":false,"loc":"US","locs":["US"],"hq":"US","co":"WhatsApp LLC (UK users); WhatsApp Ireland Limited (EEA users)","par":"Meta Platforms, Inc.","parc":"US","store":"Plan assumed: free personal WhatsApp accounts used for work groups. Messages are end-to-end encrypted and stored on each member's phone. WhatsApp keeps undelivered messages and media encrypted on its servers for up to 30 days. Other account data is shared globally within Meta, including the US. No UK or EU storage option exists.","res":"no","plans":null,"mfa":"all plans","ai":"no","aid":"Ordinary messages are end-to-end encrypted and are not used to train Meta AI. Anything sent to Meta AI, including when someone types @Meta AI in a group, is not end-to-end encrypted and can be used under Meta's privacy policy. Advanced Chat Privacy, off by default, disables some Meta AI features in a chat.","np":null,"note":"Work messages live on staff and volunteers' own phones, so the charity has no central copy and cannot control what leaves with them. Anyone typing @Meta AI in a group sends that part of the chat to Meta unencrypted.","conf":"medium","src":[["WhatsApp Privacy Policy - UK","https://www.whatsapp.com/legal/privacy-policy-uk"],["WhatsApp Privacy Policy - EEA","https://www.whatsapp.com/legal/privacy-policy-eea"],["What WhatsApp's Advanced Chat Privacy Really Does - EFF","https://www.eff.org/deeplinks/2025/09/what-whatsapps-advanced-chat-privacy-really-does"],["About registration and two-step verification - WhatsApp Help Center","https://faq.whatsapp.com/506595211487528"]]},{"id":"whatsapp-business","name":"WhatsApp Business app","job":"Messaging with supporters","k":"Software","w":"Elsewhere","b":"Elsewhere","x":"Partial","o":false,"loc":"US","locs":["US"],"hq":"US","co":"WhatsApp LLC (UK users); WhatsApp Ireland Limited (EEA users)","par":"Meta Platforms, Inc.","parc":"US","store":"Plan assumed: the free WhatsApp Business app (not the paid Business Platform API). Chats are stored on the phone the business number is registered on. Other data is shared globally within Meta, including the US. No UK or EU storage option exists.","res":"no","plans":null,"mfa":"all plans","ai":"no","aid":"Messages are end-to-end encrypted and not used to train Meta AI. Any AI tools the business connects are governed by their own terms. Messages sent to Meta AI are not end-to-end encrypted.","np":null,"note":"The app is tied to one phone number and one phone, so decide who holds that phone and how chats are kept when staff change. UK accounts are provided by WhatsApp LLC in the US.","conf":"medium","src":[["WhatsApp Business App Privacy Policy","https://www.whatsapp.com/legal/business-app-privacy-policy"],["WhatsApp Privacy Policy - UK","https://www.whatsapp.com/legal/privacy-policy-uk"],["WhatsApp Privacy Policy - EEA","https://www.whatsapp.com/legal/privacy-policy-eea"],["What WhatsApp's Advanced Chat Privacy Really Does - EFF","https://www.eff.org/deeplinks/2025/09/what-whatsapps-advanced-chat-privacy-really-does"],["About registration and two-step verification - WhatsApp Help Center","https://faq.whatsapp.com/506595211487528"]]},{"id":"signal","name":"Signal","job":"Secure messaging","k":"Software","w":"Elsewhere","b":"Elsewhere","x":"No","o":true,"loc":"US","locs":["US"],"hq":"US","co":"Signal Messenger LLC","par":"Signal Technology Foundation","parc":"US","store":"Plan assumed: the free Signal app. Messages are end-to-end encrypted and stored on members' devices. Signal's servers only queue encrypted messages for offline devices. Its terms say encrypted information and metadata are transferred to the US and other countries. Signal says it can only provide a user's registration date and last connection date.","res":"no","plans":null,"mfa":"all plans","ai":"not-applicable","aid":"Signal cannot read message content, which is end-to-end encrypted, and offers no AI features that use it.","np":null,"note":"Signal holds almost no data about you, but the charity has no admin controls or central copy of chats. Switch on Registration Lock with a PIN to stop someone taking over an account.","conf":"medium","src":[["Signal Terms of Service & Privacy Policy","https://signal.org/legal/"],["Signal Government Communication","https://signal.org/bigbrother/"],["Introducing Signal Secure Backups","https://signal.org/blog/introducing-secure-backups/"],["Signal PIN - Signal Support","https://support.signal.org/hc/en-us/articles/360007059792-Signal-PIN"],["Signal on GitHub","https://github.com/signalapp"]]},{"id":"element","name":"Element (hosted)","job":"Secure team chat","k":"Software","w":"Don't know","b":"UK or Europe","x":"Partial","o":false,"loc":"","locs":[],"hq":"GB","co":"Element Creations Ltd (trading as Element)","par":null,"parc":null,"store":"Plan assumed: an Element-hosted server (Element Matrix Services / Element Cloud). Element hosts on Amazon Web Services, with its admin server in Amsterdam and deployment server in Stockholm. Customers choose the location of their own server when they set it up; the list of locations is not published.","res":"unclear","plans":"Location is chosen at set-up for hosted servers. Element's current public pricing page lists only self-hosted plans (Community free for up to 100 users; Enterprise from 100 users), so the small-organisation hosted offer is unclear.","mfa":"unclear","ai":"not-applicable","aid":"Element's privacy policy does not mention AI or machine learning training. It says nobody at Element or its processors can access encrypted data.","np":null,"note":"Check which hosting location was picked when your server was set up, and use your own domain so you can move later. Element's published prices now focus on self-hosting.","conf":"low","src":[["Element Privacy Policy","https://element.io/legal/privacy"],["Element Company information","https://element.io/legal/company-information"],["Element plans and pricing","https://element.io/en/pricing"],["Element Server Suite","https://element.io/en/server-suite"],["Element Cloud Documentation","https://ems-docs.element.io/books/element-cloud-documentation/export/html"]]},{"id":"jitsi-meet","name":"Jitsi Meet (meet.jit.si)","job":"Video meetings","k":"Software","w":"Don't know","b":"Elsewhere","x":"Partial","o":true,"loc":"","locs":[],"hq":"US","co":"8x8, Inc.","par":null,"parc":null,"store":"Plan assumed: the free public service at meet.jit.si. 8x8 does not say where its servers are. Chat is only kept during the meeting, recordings are held for up to 24 hours until uploaded to your Dropbox, and audio and video are not stored. 8x8 stores the account that created each room.","res":"unclear","plans":null,"mfa":"unclear","ai":"unclear","aid":"The meet.jit.si privacy supplement (last updated August 2023) does not mention AI. It says 8x8 uses personal information to deliver and improve the service.","np":"Free to use.","note":"meet.jit.si is free and keeps little meeting content, but 8x8 does not say where its servers are. Since August 2023 whoever starts a meeting must sign in with Google, GitHub or Facebook.","conf":"medium","src":[["meet.jit.si Privacy Supplement","https://jitsi.org/meet-jit-si-privacy/"],["meet.jit.si Terms of Service","https://jitsi.org/meet-jit-si-terms-of-service/"],["Jitsi Meet Security & Privacy","https://jitsi.org/security/"],["Authentication on meet.jit.si","https://jitsi.org/blog/authentication-on-meet-jit-si/"],["About Jitsi","https://jitsi.org/about/"]]},{"id":"mattermost-cloud","name":"Mattermost Cloud","job":"Team chat","k":"Software","w":"Elsewhere","b":"Elsewhere","x":"Yes","o":false,"loc":"US","locs":["US"],"hq":"US","co":"Mattermost, Inc.","par":null,"parc":null,"store":"Plan assumed: Mattermost Cloud, which is now sold only through Mattermost sales as an annual subscription with a 100-user minimum. Cloud data, including messages, files, logs and backups, is stored in AWS us-east-1 in Virginia, US.","res":"yes-on-request","plans":"No published EU or UK region. Mattermost says to contact its sales team or a partner for residency outside the US, or to self-host.","mfa":"all plans","ai":"unclear","aid":"Mattermost's AI Agents connect to a language model provider that the admin configures. No statement found on whether Mattermost trains models on customer data.","np":"Nonprofit licence: 3 years of self-hosted Mattermost Professional for up to 1,000 users for US$250. Larger nonprofits are reviewed case by case, including for Cloud.","note":"Mattermost Cloud is hosted in the US and needs at least 100 paid users. The nonprofit licence covers self-hosting, which puts the data wherever you host it.","conf":"medium","src":[["Cloud data residency - Mattermost documentation","https://docs.mattermost.com/administration-guide/manage/cloud-data-residency"],["Cloud - Mattermost documentation","https://docs.mattermost.com/product-overview/cloud-subscriptions"],["Mattermost Pricing","https://mattermost.com/pricing/"],["Multi-factor authentication - Mattermost documentation","https://docs.mattermost.com/administration-guide/onboard/multi-factor-authentication.html"],["Bulk export data - Mattermost documentation","https://docs.mattermost.com/administration-guide/manage/bulk-export-tool.html"],["Non-Profit Subscriptions - Mattermost documentation","https://docs.mattermost.com/product-overview/non-profit-subscriptions.html"],["Agents admin guide - Mattermost documentation","https://docs.mattermost.com/administration-guide/configure/agents-admin-guide.html"],["mattermost/mattermost on GitHub","https://github.com/mattermost/mattermost"]]}]},{"g":"AI tools","items":[{"id":"chatgpt","name":"ChatGPT","job":"AI chat assistant","k":"AI tool","w":"Elsewhere","b":"Elsewhere","x":"Partial","o":false,"loc":"US","locs":["US"],"hq":"US","co":"OpenAI","par":null,"parc":null,"store":"Not stored in the UK or EU by default. Personal plans and ChatGPT Business have no data residency option. ChatGPT Enterprise and Edu customers can choose to store content at rest in Europe or the UK.","res":"yes-some-plans","plans":"ChatGPT Enterprise, ChatGPT Edu and eligible API customers (Europe and UK storage at rest; expanded to more regions in November 2025). Not ChatGPT Business, Free or Plus.","mfa":"all plans","ai":"depends-on-plan","aid":"Free, Go, Plus and Pro (personal): chats are used to train models by default. Opt out by turning off 'Improve the model for everyone' in Settings > Data controls, or via the OpenAI Privacy Portal ('Do not train on my content'). Giving thumbs up or down feedback can still send that whole conversation for training. ChatGPT Business (formerly Team), Enterprise, Edu and the API: not used for training by default; an organisation can opt in.","np":"OpenAI for Nonprofits: ChatGPT Business Standard seats at $8 per user per month (annual) or $10 (monthly) after Goodstack verification; up to 75% off Enterprise for larger nonprofits via sales.","note":"Personal ChatGPT accounts train on your chats unless each person turns this off, so staff should not use personal accounts for charity work. ChatGPT Business does not train on your data but stores it outside the UK and EU; only Enterprise offers UK or European storage.","conf":"high","src":[["How your data is used to improve model performance (OpenAI Help Center)","https://help.openai.com/en/articles/5722486-how-your-data-is-used-to-improve-model-performance"],["Business data privacy, security, and compliance (OpenAI)","https://openai.com/business-data/"],["Expanding data residency access to business customers worldwide (OpenAI)","https://openai.com/index/expanding-data-residency-access-to-business-customers-worldwide/"],["Introducing data residency in Europe (OpenAI)","https://openai.com/index/introducing-data-residency-in-europe/"],["Enterprise privacy at OpenAI","https://openai.com/enterprise-privacy/"],["How do I export my ChatGPT history and data? (OpenAI Help Center)","https://help.openai.com/en/articles/7260999-how-do-i-export-my-chatgpt-history-and-data"],["Does ChatGPT support multi-factor authentication? (OpenAI Help Center)","https://help.openai.com/en/articles/7967234-does-chatgpt-support-multi-factor-authentication-mfa"],["OpenAI for Nonprofits (OpenAI Help Center)","https://help.openai.com/en/articles/9359041-openai-for-nonprofits"]]},{"id":"claude","name":"Claude","job":"AI chat assistant","k":"AI tool","w":"Elsewhere","b":"Elsewhere","x":"Yes","o":false,"loc":"US","locs":["US"],"hq":"US","co":"Anthropic PBC","par":null,"parc":null,"store":"Stored in the US on all Claude plans. Processing may be routed to the US, Europe, Asia and Australia. No UK or EU storage option for Claude Team or Enterprise.","res":"no","plans":null,"mfa":"unclear","ai":"depends-on-plan","aid":"Free, Pro and Max (consumer): since 28 August 2025 each user chooses whether chats and coding sessions are used for training; existing users had to decide by 8 October 2025. If allowed, data is kept for up to five years; if not, the usual 30-day retention applies. Change it any time in Settings > Privacy (model improvement setting); incognito chats are never used. Team, Enterprise, API, Government and Education: not used for training by default.","np":"Claude for Nonprofits: Team plan at $8 per user per month and Enterprise at $10, verified through Goodstack; Anthropic's page lists US 501(c)(3) organisations as eligible, so check whether UK or EU charities qualify.","note":"Personal Claude accounts may use chats for training if the person allowed it in the 2025 privacy prompt, so check Settings > Privacy. All Claude data is stored in the US, with no UK or EU storage option on any plan.","conf":"high","src":[["Updates to Consumer Terms and Privacy Policy (Anthropic)","https://www.anthropic.com/news/updates-to-our-consumer-terms"],["Is my data used for model training? Consumer (Anthropic Privacy Center)","https://privacy.claude.com/en/articles/10023580-is-my-data-used-for-model-training"],["Is my data used for model training? Commercial (Anthropic Privacy Center)","https://privacy.claude.com/en/articles/7996868-is-my-data-used-for-model-training"],["Where are your servers located? (Anthropic Privacy Center)","https://privacy.claude.com/en/articles/7996890-where-are-your-servers-located-do-you-host-your-models-on-eu-servers"],["Data residency (Claude Platform Docs)","https://platform.claude.com/docs/en/manage-claude/data-residency"],["Export your Claude data (Claude Help Center)","https://support.claude.com/en/articles/9450526-how-can-i-export-my-claude-data"],["Getting started with Claude for Nonprofits (Claude Academy)","https://academy.claude.com/tutorials/getting-started-with-claude-for-nonprofits"]]},{"id":"google-gemini","name":"Google Gemini","job":"AI chat assistant","k":"AI tool","w":"Don't know","b":"Elsewhere","x":"Partial","o":false,"loc":"","locs":[],"hq":"US","co":"Google LLC","par":"Alphabet Inc.","parc":"US","store":"Not stated for personal accounts or ordinary Workspace plans. Workspace admins can keep Gemini data in the EU only on Enterprise Plus, Frontline Plus, Education editions or Assured Controls add-ons. The UK is not offered as a separate region.","res":"yes-some-plans","plans":"Workspace Enterprise Plus and Frontline Plus (EU processing and storage), Education Standard and Plus (EU storage only), Assured Controls add-ons. Not Workspace for Nonprofits, Business Starter or personal accounts.","mfa":"all plans","ai":"depends-on-plan","aid":"Personal Google account (Gemini app): with Keep Activity on, which is the default, chats and uploads are used to improve Google's services, including training generative AI models, and a subset is reviewed by humans (kept up to 3 years, detached from the account). Turn off Keep Activity or use Temporary chats; chats are then kept for 72 hours and not used for training, unless you send feedback. Gemini in Google Workspace (work or school account): customer data is not used to train models without permission and is not human reviewed.","np":"Google for Nonprofits: Gemini app and Gemini Notebook are included in the no-cost Google Workspace for Nonprofits plan, with up to 75% off advanced Workspace editions for eligible nonprofits.","note":"Staff using Gemini on personal Google accounts have their chats used for training and possibly read by reviewers unless they turn off Keep Activity. Use Gemini through the charity's Workspace account, where your data is not used for training.","conf":"medium","src":[["Gemini Apps Privacy Hub (Google)","https://support.google.com/gemini/answer/13594961"],["Generative AI in Google Workspace Privacy Hub","https://knowledge.workspace.google.com/admin/generative-ai/generative-ai-in-google-workspace-privacy-hub"],["Data regions support for the Gemini app (Google Workspace Updates)","https://workspaceupdates.googleblog.com/2026/06/gemini-app-data-regions-support.html"],["Data regions support for Gemini features in Google Workspace (Google Workspace Updates)","https://workspaceupdates.googleblog.com/2025/06/data-regions-support-for-gemini-features-in-google-workspace.html"],["Choose a geographic location for your data (Google Workspace Admin Help)","https://knowledge.workspace.google.com/admin/compliance/choose-a-geographic-location-for-your-data"],["The best of Google AI is now included in Workspace (Google for Nonprofits Help)","https://support.google.com/nonprofits/answer/15873832"],["Turn on 2-Step Verification (Google Account Help)","https://support.google.com/accounts/answer/185839"]]},{"id":"microsoft-365-copilot","name":"Microsoft 365 Copilot and Copilot Chat","job":"AI assistant in Office","k":"AI tool","w":"UK, EU or EEA","b":"Elsewhere","x":"Partial","o":false,"loc":"GB","locs":["GB","EU"],"hq":"US","co":"Microsoft Corporation","par":null,"parc":null,"store":"Prompts and responses are stored in the organisation's Microsoft 365 tenant (Exchange), so they follow the tenant's data location. EU tenants are covered by the EU Data Boundary, with exceptions. UK in-country processing was promised from late 2025, later adjusted to the end of 2026.","res":"yes-default","plans":"Any Microsoft 365 work or school tenant located in the UK or EU, including Copilot Chat included with Microsoft 365 subscriptions.","mfa":"all plans","ai":"no","aid":"For work or school (Entra ID) accounts, prompts, responses and data accessed through Microsoft Graph are not used to train foundation models, in both Microsoft 365 Copilot and Copilot Chat with enterprise data protection (green shield). This does not cover the consumer Microsoft Copilot app used with a personal Microsoft account.","np":"Copilot Chat is included at no extra cost with eligible Microsoft 365 subscriptions, including nonprofit plans (Business Basic grant for up to 300 users; Business Premium at $5.50 per user per month). No separate nonprofit price for Microsoft 365 Copilot Business was shown on Microsoft's nonprofit pricing page.","note":"Since 17 April 2026 Microsoft can process EU tenants' Copilot requests outside the EU at busy times (flex routing) unless an admin turns this off. Anthropic models and Bing web search in Copilot also sit outside the EU Data Boundary, so check these settings in the Microsoft 365 admin centre.","conf":"medium","src":[["Data, Privacy, and Security for Microsoft 365 Copilot (Microsoft Learn)","https://learn.microsoft.com/en-us/microsoft-365/copilot/microsoft-365-copilot-privacy"],["Microsoft Copilot Chat privacy and protections (Microsoft Learn)","https://learn.microsoft.com/en-us/copilot/privacy-and-protections"],["Microsoft offers in-country data processing to 15 countries (Microsoft Copilot blog, 4 Nov 2025)","https://www.microsoft.com/en-us/copilot/blog/2025/11/04/microsoft-offers-in-country-data-processing-to-15-countries-to-strengthen-sovereign-controls-for-microsoft-365-copilot/"],["Microsoft 365 Copilot Flex Routing (ChangePilot)","https://changepilot.cloud/blog/microsoft-365-copilot-flex-routing-eu-data-boundary-mc1269223"],["Data Residency for Microsoft 365 Copilot and Copilot Chat (Microsoft Learn)","https://learn.microsoft.com/en-us/microsoft-365/enterprise/m365-dr-service-copilot?view=o365-worldwide"],["Microsoft 365 plans for nonprofits (Microsoft)","https://www.microsoft.com/en-us/microsoft-365/business/nonprofit-plans-and-pricing"],["Security defaults in Microsoft Entra ID (Microsoft Learn)","https://learn.microsoft.com/en-us/entra/fundamentals/security-defaults"]]},{"id":"mistral-le-chat","name":"Mistral Vibe (was Le Chat)","job":"AI chat assistant","k":"AI tool","w":"UK, EU or EEA","b":"UK or Europe","x":"Yes","o":false,"loc":"EU","locs":["EU"],"hq":"FR","co":"Mistral AI SAS","par":null,"parc":null,"store":"Hosted in the EU by default. Some features may transfer data temporarily outside the EU to listed subprocessors; Enterprise customers can switch some of those features off.","res":"yes-default","plans":"All plans","mfa":"all plans","ai":"depends-on-plan","aid":"Free: chats are used for training by default; opt out in the admin or privacy settings ('Allow your interactions to be used to train our models') or in the mobile app under Data & Account Controls. Pro: Mistral's pages conflict (the help centre says users are not opted out by default, the product docs say Pro is not trained on by default), so check the toggle. Team: admins can switch training off for the whole organisation; the docs say it is off by default. Enterprise: opted out by default. Thumbs up or down feedback can be used for training on any plan.","np":null,"note":"Le Chat was renamed Vibe on 12 August 2026; accounts and data carried over. Data is hosted in the EU, but check the training toggle in the admin panel, especially on Free and Pro.","conf":"medium","src":[["Do you use my user data to train your AI models? (Mistral Help Center)","https://help.mistral.ai/en/articles/347617-do-you-use-my-user-data-to-train-your-artificial-intelligence-models"],["Can I opt out of my input or output data being used for training? (Mistral Help Center)","https://help.mistral.ai/en/articles/455207-can-i-opt-out-of-my-input-or-output-data-being-used-for-training"],["Privacy (Mistral docs)","https://docs.mistral.ai/admin/security-access/privacy"],["Where do you store my data? (Mistral Help Center)","https://help.mistral.ai/en/articles/347629-where-do-you-store-my-data-or-my-organization-s-data"],["How do I export my data from Vibe? (Mistral Help Center)","https://help.mistral.ai/en/articles/347623-how-do-i-export-my-data-from-vibe"],["Le Chat is now Vibe (Mistral Help Center)","https://help.mistral.ai/en/articles/682992-le-chat-is-now-vibe"],["As an admin on Team plan or Enterprise, do I have company-wide controls? (Mistral Help Center)","https://help.mistral.ai/en/articles/455796-as-an-admin-on-team-plan-or-enterprise-do-i-have-company-wide-controls"],["Pricing (Mistral AI)","https://mistral.ai/pricing"]]},{"id":"otter-ai","name":"Otter.ai","job":"Meeting transcription","k":"AI tool","w":"Elsewhere","b":"Elsewhere","x":"Yes","o":false,"loc":"US","locs":["US"],"hq":"US","co":"Otter.ai, Inc.","par":null,"parc":null,"store":"US by default. Otter uses Amazon Web Services in the United States and relies on the Data Privacy Framework and Standard Contractual Clauses for UK and EU transfers. No UK or EU storage option found.","res":"no","plans":null,"mfa":"all plans","ai":"yes","aid":"Otter trains its own AI on de-identified audio recordings and on transcripts, which may contain personal information, on all plans. Human review of recordings for training needs the user's permission, which can be changed in account settings. Only Enterprise customers can also opt out of the de-identified data use.","np":null,"note":"Otter trains its AI on de-identified recordings and transcripts of your meetings, and only Enterprise customers can opt out. Data is stored in the US.","conf":"medium","src":[["Privacy Policy (Otter.ai)","https://otter.ai/privacy-policy"],["Security (Otter.ai)","https://otter.ai/security"],["Pricing (Otter.ai)","https://otter.ai/pricing"],["Otter Help Center export article","https://help.otter.ai/hc/en-us/articles/360047733634-Otter-data-privacy"]]},{"id":"fireflies-ai","name":"Fireflies.ai","job":"Meeting transcription","k":"AI tool","w":"Elsewhere","b":"Elsewhere","x":"Yes","o":false,"loc":"US","locs":["US"],"hq":"US","co":"Fireflies.ai Corp.","par":null,"parc":null,"store":"Stored on servers in the United States and other countries. Enterprise customers can buy private storage at a location they choose.","res":"yes-some-plans","plans":"Enterprise (private storage)","mfa":"unclear","ai":"no","aid":"Fireflies says it does not use personal information or meeting content for AI model training and contractually bars its AI vendors from training on it, with zero data retention at those vendors. Applies to all plans.","np":null,"note":"Fireflies does not train AI on your meetings, but recordings and transcripts are stored in the US unless you pay for Enterprise private storage. Tell meeting guests the notetaker is recording.","conf":"medium","src":[["Privacy Policy (Fireflies.ai)","https://fireflies.ai/privacy-policy"],["Security (Fireflies.ai)","https://fireflies.ai/security"],["Pricing (Fireflies.ai)","https://fireflies.ai/pricing"],["How to Download Transcripts, Summaries, and Meeting Recordings (Fireflies Knowledge Base)","https://guide.fireflies.ai/hc/en-us/articles/360020247558"]]},{"id":"zoom-ai-companion","name":"Zoom AI Companion","job":"Meeting summaries","k":"AI tool","w":"Don't know","b":"Elsewhere","x":"Don't know","o":false,"loc":"","locs":[],"hq":"US","co":"Zoom Communications, Inc.","par":null,"parc":null,"store":"Follows the region the Zoom account is hosted in, which is not stated for new UK or EU accounts. Admins on Pro and above can choose Germany for recordings and some content, but out-of-meeting chat and account data stay in the provisioned region. The UK is not in the storage list.","res":"yes-some-plans","plans":"Pro and above can pick Germany for recordings, transcripts and some content; accounts hosted in the EU use Zoom-managed models (ZM+) to respect data residency.","mfa":"unclear","ai":"no","aid":"Zoom says it does not use audio, video, chat, screen sharing, attachments or other communications-like content to train its own or third-party AI models. For US-hosted accounts AI Companion sends content to third-party models (Anthropic, OpenAI, Google) under zero data retention terms; admins can ask Zoom Support for Zoom-hosted-only processing (ZMO).","np":null,"note":"Zoom does not train AI on your meeting content, but by default AI Companion may send it to third-party AI providers for processing. Ask Zoom which region your account is hosted in and which AI processing option applies.","conf":"medium","src":[["Zoom Privacy Statement","https://www.zoom.com/en/trust/privacy/privacy-statement/"],["Models, Processing, Storage, and Usage (Zoom AI whitepaper)","https://library.zoom.com/ai/ai-whitepaper/models-processing-storage-and-usage.md"],["Data Governance and Privacy (Zoom AI whitepaper)","https://library.zoom.com/ai/ai-whitepaper/data-governance-and-privacy.md"],["Managing Data & Storage location (Zoom Support)","https://support.zoom.com/hc/en/article?id=zm_kb&sysparm_article=KB0066473"]]}]},{"g":"Supporters and fundraising","items":[{"id":"mailchimp","name":"Mailchimp","job":"Newsletter","k":"Software","w":"Elsewhere","b":"Elsewhere","x":"Yes","o":false,"loc":"US","locs":["US"],"hq":"US","co":"The Rocket Science Group LLC (Intuit Mailchimp)","par":"Intuit Inc.","parc":"US","store":"US by default for all customers (assumed plan: Essentials or Standard). No EU or UK hosting option. Transfers rely on the EU-US Data Privacy Framework and UK Extension, with SCCs as fallback.","res":"no","plans":null,"mfa":"all plans","ai":"yes","aid":"Terms section 30 lets Mailchimp use generative AI Inputs and Outputs, including Customer Data, for machine learning to develop the AI model and services. Section 17 lets it aggregate and anonymise campaign content for its own use. The terms point to data preferences in account settings but do not describe a full opt-out.","np":"15% off marketing plans. Non-US nonprofits can apply with their website; request before buying, as it is not applied retroactively.","note":"Supporter data is stored in the US and there is no UK or EU hosting option. Check the data preferences in your account settings if you use the AI writing features.","conf":"high","src":[["Mailchimp and European Data Transfers","https://mailchimp.com/help/mailchimp-european-data-transfers/"],["Mailchimp Data Security and Privacy","https://mailchimp.com/about/security/"],["Set Account Security Options","https://mailchimp.com/help/set-account-security-options/"],["Mailchimp's Standard Terms of Use","https://mailchimp.com/legal/terms/"],["Export and Back Up Account Data","https://mailchimp.com/help/export-back-up-data/"],["About the Nonprofit Discount","https://mailchimp.com/help/about-nonprofit-discount/"]]},{"id":"brevo","name":"Brevo","job":"Newsletter and CRM","k":"Software","w":"UK, EU or EEA","b":"UK or Europe","x":"Yes","o":false,"loc":"FR","locs":["FR","DE","BE"],"hq":"FR","co":"Sendinblue SAS (trading as Brevo)","par":null,"parc":null,"store":"EU for all customers (assumed plan: Starter). Hosted with OVH in France and Germany and Google Cloud in Belgium.","res":"yes-default","plans":"All plans","mfa":"all plans","ai":"yes","aid":"Terms allow Brevo to use Content and Usage Data to train its AI features, limited to improving the services, in particular fraud, phishing and spam prevention and security. Other AI features can be managed in the Control Center, but fraud and spam detection cannot be switched off. Third-party AI providers only process data to provide the feature.","np":"20% off any paid monthly or yearly plan for verified nonprofits; contact support with proof of status.","note":"Data is held in the EU by default. Brevo can use your content to train its anti-spam and fraud AI, and that cannot be switched off.","conf":"high","src":[["Data storage location","https://help.brevo.com/hc/en-us/articles/360001005510-Data-storage-location"],["Data Security and Privacy","https://www.brevo.com/features/data-security/"],["Secure your account with two-factor authentication (2FA)","https://help.brevo.com/hc/en-us/articles/360021203440-Secure-your-account-with-two-factor-authentication-2FA"],["Brevo Terms of Service","https://www.brevo.com/legal/termsofuse/"],["Export your contacts from Brevo","https://help.brevo.com/hc/en-us/articles/5310065850642-Export-your-contacts-from-Brevo"],["Brevo for NGOs","https://www.brevo.com/company/ngos/"]]},{"id":"cleverreach","name":"CleverReach","job":"Newsletter","k":"Software","w":"UK, EU or EEA","b":"UK or Europe","x":"Yes","o":false,"loc":"DE","locs":["DE","EU"],"hq":"DE","co":"CleverReach GmbH & Co. KG","par":"CRASH group of companies","parc":"DE","store":"Germany and the EU for all customers (assumed plan: Basic). The supplier says servers are exclusively in Germany and the EU.","res":"yes-default","plans":"All plans","mfa":"some plans","ai":"unclear","aid":"The AI Content Generator sends your prompt to OpenAI. CleverReach does not say whether prompts are used for training or where OpenAI processes them. It is an optional feature on Basic and above. No statement found on training with recipient data.","np":"Discount for nonprofits on request; amount not published.","note":"Recipient data stays in Germany and the EU. Full two-factor login is listed only on Enterprise; smaller plans can switch on an emailed PIN code at login under Settings.","conf":"medium","src":[["Data Security - CleverReach","https://www.cleverreach.com/en/data-security/"],["GDPR-compliant newsletter tool Made in Germany","https://www.cleverreach.com/en/gdpr-compliant-newsletter-tool/"],["Privacy Policy - CleverReach","https://www.cleverreach.com/en/privacy-policy/"],["Pricing","https://www.cleverreach.com/en/plans-and-pricing/"],["Secure login with PIN code","https://support.cleverreach.com/hc/en-us/articles/17799104835602-Secure-login-with-PIN-code"],["AI Content Generator for Beautiful Email Copy","https://www.cleverreach.com/en/newsletter-tool/creating-and-designing-newsletters/ai-content-generator/"],["Export of adresses of a segment","https://support.cleverreach.com/hc/en-us/articles/360035176194-Export-of-adresses-of-a-segment"]]},{"id":"beacon-crm","name":"Beacon CRM","job":"Supporter CRM","k":"Software","w":"UK, EU or EEA","b":"UK or Europe","x":"Yes","o":false,"loc":"GB","locs":["GB","IE"],"hq":"GB","co":"Beacon (beaconcrm.org)","par":null,"parc":null,"store":"UK by default (assumed plan: Starter). Trust page says data is hosted exclusively in the UK on AWS; the sub-processor list names AWS London and Ireland and Google Cloud London for core storage.","res":"yes-default","plans":"All plans","mfa":"all plans","ai":"no","aid":"Beacon says Beacon AI cannot access your data and does not use it to train public AI models. The AI provider behind Beacon AI is not named in the sub-processor list.","np":null,"note":"Data is held in the UK. In late July 2026 attackers copied Beacon's customer database backups, affecting over 1,000 charities, so check what Beacon has told you and whether you have acted on it.","conf":"high","src":[["Beacon Trust","https://www.beaconcrm.org/trust"],["Beacon Sub-processors","https://www.beaconcrm.org/legal/sub-processors"],["Export your data","https://guide.beaconcrm.org/en/articles/5717571-export-your-data"],["Beacon Pricing and Plans","https://www.beaconcrm.org/pricing"],["Over 1,000 Charities Hit by Beacon CRM Data Breach","https://www.securityweek.com/over-1000-charities-hit-by-beacon-crm-data-breach/"],["Beacon CRM cyber incident: what Scottish charities should do now","https://scvo.scot/p/106392/2026/08/04/beacon-crm-cyber-incident-what-scottish-charities-should-do-now"]]},{"id":"salesforce-nonprofit-cloud","name":"Salesforce Nonprofit","job":"Supporter CRM","k":"Software","w":"Don't know","b":"Elsewhere","x":"Yes","o":false,"loc":"","locs":[],"hq":"US","co":"Salesforce, Inc.","par":null,"parc":null,"store":"Depends on the region the org is provisioned in (assumed plan: Power of Us donated Enterprise Edition). Hyperforce runs in the UK, Germany and other countries, and data is generally stored in the country where the org is located. The Hyperforce EU Operating Zone adds stronger EU and Swiss residency commitments but is not offered for the UK. Generative AI features may route data to LLM providers such as OpenAI or Azure.","res":"yes-on-request","plans":"Hyperforce orgs provisioned in a UK or EU region; EU Operating Zone for EU and Swiss customers","mfa":"all plans","ai":"yes","aid":"Salesforce says generative AI features are not trained on customer data, but predictive Einstein features can use org data for global models. Since the Spring 2026 release admins can switch this off under Setup > Opt Out of Customer Data Access; most orgs start opted in.","np":"Power of Us programme: 10 donated Enterprise Edition licences of Agentforce Nonprofit (or Sales and Service Cloud) for eligible nonprofits.","note":"Check your instance location on my.trust.salesforce.com, because storage depends on where your org was set up. Ask your admin to review the Opt Out of Customer Data Access setting, which starts switched to allow data use.","conf":"medium","src":[["Hyperforce: Public Cloud Infrastructure","https://www.salesforce.com/uk/platform/public-cloud-infrastructure/"],["Hyperforce: European Union Public Cloud Infrastructure","https://www.salesforce.com/uk/platform/data-residence-eu-oz/"],["Salesforce Infrastructure and Sub-processors","https://www.salesforce.com/en-us/wp-content/uploads/sites/4/documents/legal/misc/salesforce-infrastructure-and-subprocessors.pdf"],["Where is my Salesforce instance located?","https://help.salesforce.com/s/articleView?id=000396845&language=en_US&type=1"],["Debunking Myths: Salesforce Einstein and Agentforce","https://www.salesforce.com/blog/debunking-myths-salesforce-einstein-and-agentforce/"],["Salesforce AI Data Sharing Opt Out: What Nonprofits, Associations and Foundations Need to Know","https://fionta.com/insights/salesforce-ai-data-sharing-opt-out-what-nonprofits-associations-and-foundations-need-to-know/"],["Salesforce Data Export FAQ","https://help.salesforce.com/s/articleView?id=000383962&language=en_US&type=1"],["How to Prepare for Salesforce's Mandatory MFA Changes in 2026","https://www.salesforceben.com/how-to-prepare-for-salesforces-mandatory-mfa-changes-in-2026/"],["The State of Salesforce Nonprofit Offerings in 2026","https://www.salesforceben.com/the-state-of-salesforce-nonprofit-offerings-in-2026/"]]},{"id":"civicrm","name":"CiviCRM","job":"Supporter CRM","k":"Software","w":"Don't know","b":"Elsewhere","x":"Yes","o":true,"loc":"","locs":[],"hq":"US","co":"CiviCRM LLC","par":null,"parc":null,"store":"Depends entirely on the host (assumed: hosted by a CiviCRM partner). Self-hosted or partner-hosted data sits wherever that server is. CiviCRM's own Spark hosting lets you choose North America or Europe.","res":"yes-on-request","plans":"Any host with UK or EU servers; Spark with the Europe option","mfa":"unclear","ai":"not-applicable","aid":"Core CiviCRM has no supplier AI service that receives your data. Check any AI extensions or host services you add.","np":"Free open-source software (AGPL 3). You pay for hosting and support; Spark hosting starts at about USD 15 a month.","note":"Where your data lives and whether two-factor login is available depend on your hosting partner and the website system CiviCRM runs on. Ask your host where the servers are and whether you can get a full database copy.","conf":"medium","src":[["License","https://civicrm.org/about/license"],["CiviCRM","https://civicrm.org/"],["Spark - CiviCRM","https://civicrm.com/spark/"],["Hosting - CiviCRM Installation Guide","https://docs.civicrm.org/installation/en/latest/planning/hosting/"],["Exporting - CiviCRM User Guide","https://docs.civicrm.org/user/en/latest/common-workflows/exporting-your-contacts/"],["Login Security - CiviCRM Documentation","https://docs.civicrm.org/loginsecurity/en/latest/"]]},{"id":"donorfy","name":"Donorfy","job":"Supporter CRM","k":"Software","w":"UK, EU or EEA","b":"UK or Europe","x":"Partial","o":false,"loc":"IE","locs":["IE"],"hq":"GB","co":"Donorfy","par":"The Access Group","parc":"GB","store":"EU by default (assumed plan: Starter). Hosted on Microsoft Azure North Europe in Dublin, Ireland. Enterprise can use private cloud hosting.","res":"yes-default","plans":"All plans","mfa":"all plans","ai":"no","aid":"Donorfy is being linked to The Access Group's Access Evo AI features. Access says Evo AI has zero data retention for training and inputs are never used to improve models. Evo features were switched on automatically from 17 November 2025 and admins can turn them off.","np":null,"note":"Data is held in Ireland. A full export with all fields and attachments costs extra, so ask for the price before you decide to leave.","conf":"medium","src":[["Donorfy Security","https://donorfy.com/security"],["Pricing","https://donorfy.com/pricing"],["Downloading your data","https://donorfy.com/downloading-data"],["The Access Group to Acquire Charity CRM Provider Donorfy","https://www.theaccessgroup.com/en-gb/about/news/the-access-group-to-acquire-charity-crm-provider-donorfy/"],["Building a new Donorfy API: What It Means for You","https://www.theaccessgroup.com/en-gb/blog/nfp-building-a-new-donorfy-api-what-it-means-for-you/"],["Access Evo Platform: FAQ","https://help-accessevo.theaccessgroup.com/en/articles/15937010-access-evo-platform-faq"]]},{"id":"hubspot","name":"HubSpot","job":"CRM and email marketing","k":"Software","w":"UK, EU or EEA","b":"Elsewhere","x":"Yes","o":false,"loc":"DE","locs":["DE"],"hq":"US","co":"HubSpot, Inc.","par":null,"parc":null,"store":"Set at sign-up by the IP address location (assumed plan: free CRM or Starter). HubSpot has an EU data centre in Germany; accounts started in the US data centre can be moved to the EU on any plan. HubSpot does not state where UK sign-ups go. Usage data and some processing still go to the US.","res":"yes-on-request","plans":"All plans (EU data centre by sign-up location or migration)","mfa":"all plans","ai":"yes","aid":"HubSpot uses customer data such as CRM activity to train its models by default. Super Admins can switch off 'AI Model Training' under Settings > AI > Access. Opt-out applies from then on only. Accounts with Sensitive Data enabled are opted out.","np":"40% off Professional and Enterprise for new annual customers, but HubSpot's page limits it to nonprofits registered in North America, Australia and New Zealand. Starter is excluded.","note":"Check Account defaults to see which data centre your account uses, as UK sign-ups may land in the US. HubSpot trains AI on your CRM data unless a Super Admin switches it off.","conf":"medium","src":[["HubSpot Cloud Infrastructure and Data Hosting FAQ","https://knowledge.hubspot.com/account-security/hubspot-cloud-infrastructure-and-data-hosting-frequently-asked-questions"],["Migrate account data to another regional data center","https://knowledge.hubspot.com/account-management/migrate-your-account-data-to-hubspots-eu-data-center"],["Two-factor authentication","https://knowledge.hubspot.com/account/two-factor-authentication-faq"],["Opt out of HubSpot's machine learning data use","https://knowledge.hubspot.com/account-management/hubspot-machine-learning-data"],["Export records","https://knowledge.hubspot.com/import-and-export/export-records"],["HubSpot for Nonprofits","https://www.hubspot.com/nonprofits"]]}]},{"g":"Donations, payments and events","items":[{"id":"justgiving","name":"JustGiving","job":"Online fundraising pages","k":"Software","w":"Don't know","b":"UK or Europe","x":"Partial","o":false,"loc":"","locs":[],"hq":"GB","co":"Giving.com Limited (JustGiving, UK); MyCharity Limited (Ireland/EEA)","par":"Blackbaud, Inc.","parc":"US","store":"Not stated. The privacy policy says some personal data may be stored outside the UK, EU or EEA, and JustGiving is covered by Blackbaud's EU-US Data Privacy Framework certification.","res":"unclear","plans":null,"mfa":"all plans","ai":"unclear","aid":"The privacy policy says JustGiving uses machine learning and analytics to make inferences about users (donors and fundraisers) to tailor content, and users can opt out. It does not say whether charity or donor data trains AI models. No statement found for charity account data.","np":"Built for charities. Start plan has no monthly fee; Grow plan is £15 or £39 a month plus VAT depending on income. No platform fee on donations; card processing 1.9% + 30p; 5% fee on Gift Aid claimed.","note":"JustGiving and your charity are separate data controllers for donor data, so donors' details sit in JustGiving's own system as well as yours. It does not say where that data is stored, so ask Blackbaud if location matters to you.","conf":"medium","src":[["JustGiving Privacy Policy v30","https://www.justgiving.com/about/info/privacy-policy/privacy-policy-v30"],["Charity Fundraising Pricing Plans","https://www.justgiving.com/for-charities/pricing"],["Understanding your donation payment reports","https://justgiving-charitysupport.zendesk.com/hc/en-us/articles/14505672461329-Understanding-your-donation-payment-reports"],["Logging in with your Blackbaud ID and Multi Factor Authentication","https://justgiving-charitysupport.zendesk.com/hc/en-us/articles/14481897979281-Logging-in-with-your-Blackbaud-ID-and-Multi-Factor-Authentication"],["What is GDPR? (UK only)","https://justgiving-charitysupport.zendesk.com/hc/en-us/articles/14508528500753-What-is-GDPR-UK-only"]]},{"id":"enthuse","name":"Enthuse","job":"Branded donations and events","k":"Software","w":"UK, EU or EEA","b":"UK or Europe","x":"Yes","o":false,"loc":"GB","locs":["GB"],"hq":"GB","co":"Online Giving Ltd (trading as Enthuse)","par":null,"parc":null,"store":"UK hosting on Microsoft Azure and AWS","res":"yes-default","plans":"All plans","mfa":"all plans","ai":"unclear","aid":"The privacy notice does not mention AI, machine learning or model training. No opt-out setting found.","np":"Charity-only product. 0% platform fee; monthly subscriptions from £0 (mass participation) to £39.99; payment fee 1.9% + 30p; 5% Gift Aid fee.","note":"Enthuse says it hosts in the UK and requires two-step verification for all admin users. Check which monthly package you are on, because features and fees differ by product.","conf":"high","src":[["Security and data - Enthuse","https://enthuse.com/security-and-data/"],["Privacy Notice - Enthuse","https://enthuse.com/privacy/"],["Pricing - Enthuse","https://enthuse.com/pricing/"],["2 Step Verification (2SV) FAQs","https://help.enthuse.com/en/articles/6842466-2-step-verification-2sv-faqs"],["Accessing and Understanding your Payment Report","https://help.enthuse.com/en/articles/11728518-accessing-and-understanding-your-payment-report"],["Importing from Enthuse (Beacon CRM)","https://guide.beaconcrm.org/en/articles/6519337-importing-from-enthuse"]]},{"id":"stripe","name":"Stripe","job":"Card payments","k":"Software","w":"Elsewhere","b":"UK or Europe","x":"Yes","o":false,"loc":"US","locs":["US"],"hq":"IE","co":"Stripe Payments Europe, Ltd. (contracting entity for UK and EEA); Stripe Technology Company Limited (data controller outside the Americas)","par":"Stripe, Inc.","parc":"US","store":"Transferred to the US (and India) by default. No UK or EU storage option found for ordinary accounts.","res":"no","plans":null,"mfa":"all plans","ai":"yes","aid":"The privacy policy (updated April 2026) lists training AI models to power services and prevent fraud. Stripe's Payments Foundation Model is trained on tens of billions of transactions across its network. No specific opt-out for model training found; rights requests go through the Privacy Center.","np":"Discounted processing on request for registered nonprofits (UK included) where at least 80% of volume is donations. Tickets, memberships and registration fees do not count.","note":"Stripe moves your payment and donor data to the US and uses transaction data to train its fraud and payments AI. Two-step login is optional, so an admin should switch on the setting that requires it for the whole team.","conf":"high","src":[["Stripe Privacy Policy","https://stripe.com/gb/privacy"],["Stripe Privacy Center","https://stripe.com/gb/legal/privacy-center"],["AI at Stripe","https://stripe.com/payments/ai"],["Fee discount for nonprofit organisations","https://support.stripe.com/questions/fee-discount-for-nonprofit-organizations?locale=en-GB"],["Export customer data without the payment details","https://support.stripe.com/questions/export-customer-data-without-the-payment-details"],["Require two-step authentication for your team","https://support.stripe.com/questions/require-two-step-authentication-for-your-team"]]},{"id":"paypal","name":"PayPal","job":"Online payments and donations","k":"Software","w":"Elsewhere","b":"UK or Europe","x":"Partial","o":false,"loc":"US","locs":["US"],"hq":"GB","co":"PayPal UK Ltd (UK accounts); PayPal Giving Fund UK is a separate registered charity (1110538)","par":"PayPal Holdings, Inc.","parc":"US","store":"Stored in the US and other countries by PayPal's service providers","res":"no","plans":null,"mfa":"all plans","ai":"yes","aid":"The UK privacy statement (28 October 2025) says personal data is used to improve services, including improving risk models and developing new products and features. No opt-out for this found. It does not use the phrase AI training.","np":"Discounted charity rate on application for confirmed charities (change business type to Non-profit and submit documents). PayPal Giving Fund enrolment is free and charges no fees to charities or donors, though partner platforms may add fees.","note":"Donations through PayPal Giving Fund go to that fund first, and you only get a donor's name and email if they chose to share them. PayPal stores data in the US.","conf":"medium","src":[["PayPal Privacy Statement (UK), last updated 28 October 2025","https://www.paypalobjects.com/marketing/ua/pdf/GB/en/privacy-full-102825.pdf"],["How do I apply for the charity rate?","https://www.paypal.com/uk/cshelp/article/how-do-i-apply-for-the-charity-rate-help221"],["PayPal Giving Fund UK Enrolment Guide","https://www.paypalobjects.com/marketing/web/PPGF/UK/PPGF%20UK%20Enrolment%20Guide.pdf"],["PayPal Giving Fund FAQ","https://www.paypal.com/uk/webapps/mpp/givingfund/help-contact"],["How do I view and download statements and reports?","https://www.paypal.com/uk/cshelp/article/how-do-i-view-and-download-statements-and-reports-help145"],["What is 2-step verification and how do I turn it on or off?","https://www.paypal.com/uk/cshelp/article/what-is-2-step-verification-and-how-do-i-turn-it-on-or-off-help167"]]},{"id":"gocardless","name":"GoCardless","job":"Direct Debit collection","k":"Software","w":"UK, EU or EEA","b":"UK or Europe","x":"Yes","o":false,"loc":"EU","locs":["EU"],"hq":"GB","co":"GoCardless Ltd","par":null,"parc":null,"store":"Main processing for European payments on servers in the EEA; some suppliers may transfer data outside the EEA","res":"yes-default","plans":"All plans","mfa":"all plans","ai":"yes","aid":"GoCardless says its Success+ retry models are trained on millions of recurring payments it has processed, and Protect+ fraud models use data from billions of transactions on its network. The merchant privacy notice (July 2026) says data is used to improve services and for automated fraud decisions. No opt-out found.","np":"Charity Pricing plan: 25% off standard transaction fees for registered charities. CICs, companies limited by guarantee without share capital, custom pricing and add-on fees are excluded.","note":"GoCardless processes European payments in the EEA and you can move your Direct Debit mandates out through a bulk change. CICs do not qualify for the charity discount.","conf":"medium","src":[["Privacy Centre - Merchants","https://gocardless.com/privacy/merchants/"],["GoCardless GDPR","https://gocardless.com/privacy/en-gdpr/"],["Charity & Non Profit FAQs","https://support.gocardless.com/hc/en-gb/articles/360000367589-Charity-Non-Profit-FAQs"],["Exporting customer information","https://support.gocardless.com/hc/en-us/articles/360000136445-Exporting-customer-information"],["Bulk changing away from GoCardless","https://support.gocardless.com/hc/en-us/articles/115005800129-Bulk-changing-away-from-GoCardless"],["Enforce 2-factor authentication for all users","https://support.gocardless.com/hc/en-us/articles/17144323905564-Enforce-2-factor-authentication-for-all-users"],["How we built Success+ using our ethical machine learning programme","https://gocardless.com/blog/how-we-built-success-plus-ethical-machine-learning/"],["GoCardless launches Protect+","https://gocardless.com/blog/gocardless-launches-protect-plus/"]]},{"id":"mollie","name":"Mollie","job":"Online payments","k":"Software","w":"Don't know","b":"UK or Europe","x":"Partial","o":false,"loc":"","locs":[],"hq":"NL","co":"Mollie B.V. (Mollie UK Ltd for UK merchants)","par":null,"parc":null,"store":"Not stated by Mollie. Its privacy statement says some processing by third parties may happen outside the EEA. A secondary profile says Mollie commits to storing payment data in European data centres.","res":"unclear","plans":null,"mfa":"all plans","ai":"yes","aid":"The privacy statement (18 July 2026) lists developing, training, using and enhancing automated systems including AI models as a purpose. No opt-out described.","np":null,"note":"Mollie says it usually offers no discount for charities, and it does not state where it stores data. Mollie treats itself as a separate controller, not your processor, so there is no data processing agreement to sign.","conf":"medium","src":[["Mollie Privacy Statement","https://www.mollie.com/legal/privacy"],["Can I use Mollie to accept donations?","https://help.mollie.com/hc/en-gb/articles/115000632489-Can-I-use-Mollie-to-accept-donations"],["How do I export my balance report, transactions, and settlements?","https://help.mollie.com/hc/en-us/articles/115000667809-How-can-I-export-transactions-and-outpayments-"],["How do I enable multi-factor authentication (MFA)?","https://help.mollie.com/hc/en-us/articles/360018584459-How-do-I-enable-multi-factor-authentication-MFA"],["Do I have to sign a data processing agreement with Mollie?","https://help.mollie.com/hc/en-us/articles/360002761193-Do-I-have-to-sign-a-data-processing-agreement-with-Mollie"],["Mollie - EU & privacy compliance profile (EU Vetted)","https://euvetted.com/p/mollie"]]},{"id":"eventbrite","name":"Eventbrite","job":"Event ticketing","k":"Software","w":"Elsewhere","b":"Elsewhere","x":"Yes","o":false,"loc":"US","locs":["US"],"hq":"US","co":"Eventbrite, Inc.","par":"Bending Spoons S.p.A.","parc":"IT","store":"US. Eventbrite says it physically stores personal data in the United States.","res":"no","plans":null,"mfa":"all plans","ai":"unclear","aid":"The privacy policy (15 September 2026) does not mention AI training. The organiser DPA says Eventbrite acts as an independent controller when it uses attendee data for research to improve products and give recommendations. No AI sub-processors listed.","np":"50% off the Eventbrite Pro marketing plan for verified nonprofits (via Percent). Ticketing fees are not discounted.","note":"Eventbrite stores attendee data in the US and can use it for its own product research and recommendations. Eventbrite was bought by Bending Spoons in March 2026, so review the terms again.","conf":"high","src":[["Eventbrite & EU Data Protection","https://www.eventbrite.co.uk/help/en-gb/articles/363929/eventbrite-data-protection/"],["Eventbrite Privacy Policy","https://www.eventbrite.co.uk/help/en-gb/articles/460838/eventbrite-privacy-policy/"],["Data Processing Addendum (DPA) for Organizers","https://www.eventbrite.com/help/en-us/articles/429030/data-processing-addendum-for-organizers/"],["Nonprofit pricing for Eventbrite Pro","https://www.eventbrite.co.uk/help/en-gb/articles/585157/can-my-nonprofit-or-charity-get-lower-fees-for-our-events/"],["Download an attendees report","https://www.eventbrite.com/help/en-us/articles/496608/download-an-attendees-report/"],["Logging in with multi-factor authentication","https://www.eventbrite.com/help/en-us/articles/277134/logging-in-with-multi-factor-authentication/"],["Eventbrite Subprocessors","https://www.eventbrite.co.uk/help/en-gb/articles/891292/eventbrite-subprocessors/"],["Eventbrite - Wikipedia","https://en.wikipedia.org/wiki/Eventbrite"]]},{"id":"pretix","name":"pretix (hosted)","job":"Event ticketing","k":"Software","w":"UK, EU or EEA","b":"UK or Europe","x":"Yes","o":false,"loc":"DE","locs":["DE"],"hq":"DE","co":"pretix GmbH","par":null,"parc":null,"store":"Germany, on servers in data centres run by German companies","res":"yes-default","plans":"All hosted accounts","mfa":"all plans","ai":"no","aid":"The privacy page says pretix does not share customer data with anyone and uses event data only to run ticket sales and calculate its fees. No AI training mentioned.","np":"Non-profit pricing on request: 2.0% per paid ticket instead of 2.5% (capped at €15 or £13), and 2,500 free tickets a year before free-ticket fees apply. pretix decides eligibility case by case.","note":"pretix hosts all data in Germany and most of its code is open source, so you could run it yourself. Two-factor login is optional, so turn on the team setting that requires it.","conf":"high","src":[["Privacy at pretix","https://pretix.eu/about/en/privacy"],["Security - pretix","https://pretix.eu/about/en/security"],["Pricing - pretix (non-profit)","https://pretix.eu/about/en/pricing?nonprofit=true"],["Data exporters - pretix REST API","https://docs.pretix.eu/dev/api/resources/exporters.html"],["Two-factor authentication - pretix Documentation","https://docs.pretix.eu/guides/two-factor-authentication/"],["pretix LICENSE (GitHub)","https://github.com/pretix/pretix/blob/master/LICENSE"]]},{"id":"ticket-tailor","name":"Ticket Tailor","job":"Event ticketing","k":"Software","w":"UK, EU or EEA","b":"UK or Europe","x":"Yes","o":false,"loc":"IE","locs":["IE","FR"],"hq":"GB","co":"Zimma Ltd (trading as Ticket Tailor)","par":null,"parc":null,"store":"EU, on AWS in Dublin (Ireland) and Paris (France)","res":"yes-default","plans":"All accounts","mfa":"all plans","ai":"unclear","aid":"The privacy policy does not mention AI or model training, and no AI sub-processors are listed. No explicit statement either way.","np":"50% off Ticket Tailor fees for registered charities, on proof of status. The help centre says other not-for-profits get 20%.","note":"Ticket Tailor stores data in Ireland and France, and registered charities can claim half-price fees. Card payments go through your own Stripe, PayPal or Square account, so check those separately.","conf":"high","src":[["GDPR - Ticket Tailor","https://www.tickettailor.com/legal/gdpr"],["Third Party Sub-Processors","https://www.tickettailor.com/legal/gdpr-third-parties"],["Privacy Policy - Ticket Tailor","https://www.tickettailor.com/legal/privacy-policy"],["I run a charity/not-for-profit organisation. Do I get a discount?","https://help.tickettailor.com/en/articles/950033-i-run-a-charity-not-for-profit-organisation-do-i-get-a-discount"],["Ticket Tailor: Pricing","https://www.tickettailor.com/en-us/pricing"],["How to export your order information","https://help.tickettailor.com/en/articles/950965-how-to-export-your-order-information"],["How to set up two-factor authentication (2FA)","https://help.tickettailor.com/en/articles/4341594-how-to-set-up-two-factor-authentication-2fa"]]}]},{"g":"Money, website and forms","items":[{"id":"xero","name":"Xero","job":"Accounting and bookkeeping","k":"Software","w":"Elsewhere","b":"Elsewhere","x":"Partial","o":false,"loc":"US","locs":["US","NZ"],"hq":"OTHER","co":"Xero Limited","par":null,"parc":null,"store":"US by default. Xero says it hosts customer data with AWS on servers in the US, and some EU customer data is processed in New Zealand.","res":"no","plans":null,"mfa":"all plans","ai":"unclear","aid":"Xero says its JAX assistant does not use customer data to train the LLMs it uses, and its AWS, Azure and GCP model providers do not retain it. Separately, the UK privacy notice says Xero uses personal data to improve services and develop new products 'using AI/ML' and offers no specific opt-out. Assumed plan: Standard or Premium business plan.","np":"25% off business pricing plans for registered not-for-profits, applied after Xero verifies charity status (claim within 31 days of subscribing).","note":"Xero stores your accounts in the US, not the UK. Export your reports, CSV lists and attachments before you ever cancel, as there is no one-click full backup.","conf":"high","src":[["Xero and GDPR: Protecting Your Personal Data","https://www.xero.com/uk/data/xero-and-gdpr/"],["Xero Privacy Notice (UK)","https://www.xero.com/uk/legal/privacy/"],["Multi-factor authentication FAQs","https://www.xero.com/us/security/multi-factor-authentication/faq/"],["Just Ask Xero (JAX)","https://www.xero.com/uk/ai-in-accounting/jax/"],["Accounting software for non-profit organisations","https://www.xero.com/uk/small-businesses/non-profit/"],["Export accounting data out of Xero","https://central.xero.com/0/article/Export-general-ledger-data-out-of-Xero"],["Leaving Xero? Everything You Need to Know About Your Data (Boxkite)","https://www.getboxkite.com/blog/leaving-xero-everything-you-need-to-know-about-your-data"]]},{"id":"quickbooks-online","name":"QuickBooks Online","job":"Accounting and bookkeeping","k":"Software","w":"Don't know","b":"Elsewhere","x":"Partial","o":false,"loc":"","locs":[],"hq":"US","co":"Intuit Limited (UK) / Intuit Inc.","par":"Intuit Inc.","parc":"US","store":"Not clearly stated. A UK help article says data is kept on AWS 'in your home country to satisfy data residency laws', but Intuit's UK GDPR page reserves the right to store and process data in the US and other countries.","res":"unclear","plans":null,"mfa":"all plans","ai":"yes","aid":"Intuit's global privacy statement says it may use personal information to improve and develop products 'by training our artificial intelligence models and other machine learning models', and creates anonymised aggregate statistics. No specific opt-out is offered beyond general UK/EU data rights such as objecting to processing. Assumed plan: Simple Start or Essentials.","np":null,"note":"Intuit does not clearly say whether UK accounts are stored in the UK, and it trains its AI models on customer data. Ask Intuit in writing where your data is held if that matters to your trustees.","conf":"medium","src":[["Privacy and security in QuickBooks (UK help)","https://quickbooks.intuit.com/learn-support/en-uk/help-article/banking/privacy-security-quickbooks/L7q2gUqfM_GB_en_GB"],["QuickBooks GDPR Centre","https://quickbooks.intuit.com/uk/gdpr/"],["Intuit Global Privacy Statement","https://www.intuit.com/privacy/statement/"],["Secure your Intuit Account with extra verification","https://quickbooks.intuit.com/learn-support/en-us/help-article/security-risk/verify-account-multi-factor-authentication/L2Xp0GNiT_US_en_US"],["Export your QuickBooks Online data","https://quickbooks.intuit.com/learn-support/en-us/help-article/list-management/export-reports-lists-data-quickbooks-online/L1xleDrLp_US_en_US"],["Accounting Software for Nonprofits (UK)","https://quickbooks.intuit.com/uk/industry/nonprofit-accounting/"]]},{"id":"sage-accounting","name":"Sage Accounting","job":"Accounting and bookkeeping","k":"Software","w":"UK, EU or EEA","b":"UK or Europe","x":"Partial","o":false,"loc":"IE","locs":["IE"],"hq":"GB","co":"The Sage Group plc","par":null,"parc":null,"store":"Ireland. Sage lists AWS in Ireland as the data hosting location for Sage Business Cloud Accounting.","res":"yes-default","plans":"All Sage Accounting plans","mfa":"all plans","ai":"yes","aid":"Sage's AI and data ethics principles say it analyses customer product data together with other customers' data 'to develop and train AI models', and that it does not offer a choice on use of anonymised data. Identifiable data is not shared with third parties without permission. Assumed plan: Sage Accounting Standard or Plus.","np":"Sage says registered charities, trusts and non-profits can save up to 50% through Sage Foundation. Check the offer is still live before relying on it.","note":"Sage keeps your accounts in Ireland, inside the EU. Sage uses anonymised customer data to train its AI and there is no opt-out for that.","conf":"medium","src":[["Customer Due Diligence - Privacy at Sage","https://www.sage.com/en-gb/trust-security/privacy/customer-due-diligence/"],["Sage Two-Factor Authentication (2FA)","https://www.sage.com/en-gb/trust-security/2fa/"],["Data ethics and principles at Sage","https://www.sage.com/en-us/trust-security/ai-ethics/"],["Accounting Software for Charities & Non-Profits","https://www.sage.com/en-gb/sage-business-cloud/sage-accounting/industry/non-profit/"],["Export your bank transactions (Sage KB)","https://help.accounting.sage.com/en-gb/accounting/reporting/export-data--accounting.html"]]},{"id":"google-analytics-4","name":"Google Analytics 4","job":"Website analytics","k":"Software","w":"Elsewhere","b":"Elsewhere","x":"Partial","o":false,"loc":"","locs":[],"hq":"US","co":"Google LLC","par":"Alphabet Inc.","parc":"US","store":"Global Google data centres, with no residency option. Traffic from UK and EU devices is collected on UK or EU servers and IP addresses are discarded, but data is then forwarded to Analytics servers for processing.","res":"no","plans":null,"mfa":"all plans","ai":"unclear","aid":"GA has data sharing settings, including 'Google products & services', which lets Google use your data to improve Google products, and 'Modeling contributions & business insights'. These are chosen at sign-up and can be changed under Admin, Account settings. Google does not state clearly on the help page which are on by default. Assumed plan: free standard GA4 property.","np":null,"note":"Google Analytics sends data outside the UK and EU and keeps detailed data for 14 months at most. Check the data sharing settings in Admin and switch off any you do not need.","conf":"medium","src":[["[GA4] EU-focused data and privacy","https://support.google.com/analytics/answer/12017362?hl=en"],["Safeguarding your data","https://support.google.com/analytics/answer/6004245"],["Data sharing settings","https://support.google.com/analytics/answer/1011397"],["[GA4] Data retention","https://support.google.com/analytics/answer/7667196"],["[GA4] Set up BigQuery Export","https://support.google.com/analytics/answer/9823238"],["Turn on 2-Step Verification","https://support.google.com/accounts/answer/185839?hl=en"]]},{"id":"plausible-analytics","name":"Plausible Analytics","job":"Website analytics","k":"Software","w":"UK, EU or EEA","b":"UK or Europe","x":"Partial","o":false,"loc":"DE","locs":["DE"],"hq":"EE","co":"Plausible Insights OÜ","par":null,"parc":null,"store":"Germany. Visitor data is stored on Hetzner servers in Falkenstein, Germany, on EU-owned infrastructure.","res":"yes-default","plans":"All cloud plans","mfa":"all plans","ai":"no","aid":"No AI training statement found. Plausible's DPA says it processes visitor data only on the customer's documented instructions, and its data policy says data is not used for advertising, profiling or monetisation. Assumed plan: Starter or Growth cloud plan.","np":"15% off Business plans on annual billing, plus 2 free months, for nonprofits. Apply by contacting Plausible for a code.","note":"Plausible keeps your website statistics in Germany with an EU company. You can only export summary figures on normal plans, not raw visit logs.","conf":"high","src":[["Plausible Privacy Policy","https://plausible.io/privacy"],["Plausible Data Policy","https://plausible.io/data-policy"],["Security Practices","https://plausible.io/security"],["Plausible Data Processing Agreement","https://plausible.io/dpa"],["Export stats","https://plausible.io/docs/export-stats"],["Discount for nonprofits and educational institutions","https://plausible.io/docs/nonprofit-and-education-pricing"],["plausible/analytics README","https://github.com/plausible/analytics"]]},{"id":"umami-cloud","name":"Umami Cloud","job":"Website analytics","k":"Software","w":"UK, EU or EEA","b":"Elsewhere","x":"Yes","o":false,"loc":"EU","locs":["EU"],"hq":"US","co":"Umami Software, Inc.","par":null,"parc":null,"store":"You pick US or European Union as the data region when you set up the account. It cannot be changed afterwards.","res":"yes-default","plans":"All cloud plans, if EU is selected at account setup","mfa":"unclear","ai":"unclear","aid":"The privacy policy says Umami does not sell or share personal information, but it says nothing about AI training. Assumed plan: Hobby (free) or Pro.","np":null,"note":"Choose European Union when you set up Umami Cloud, because the data region cannot be changed later. The company is based in the US.","conf":"medium","src":[["Umami Pricing (FAQ)","https://umami.is/pricing"],["Umami Cloud: Sign up","https://umami.is/docs/cloud/sign-up"],["Umami Cloud: Export data","https://umami.is/docs/cloud/export-data"],["Umami Privacy Policy","https://umami.is/privacy"],["umami-software/umami licence","https://github.com/umami-software/umami/blob/master/LICENSE"]]},{"id":"matomo-cloud","name":"Matomo Cloud","job":"Website analytics","k":"Software","w":"UK, EU or EEA","b":"Elsewhere","x":"Yes","o":false,"loc":"DE","locs":["DE","IE"],"hq":"OTHER","co":"InnoCraft Ltd","par":null,"parc":null,"store":"Germany. Matomo Cloud is hosted on AWS in Frankfurt, with backups in Dublin.","res":"yes-default","plans":"All Matomo Cloud plans","mfa":"all plans","ai":"no","aid":"InnoCraft acts as processor under the Matomo Cloud DPA. No AI training statement was found for customer analytics data. Matomo's website privacy policy says its AI providers receive only aggregated reports and may not train general-purpose models. Assumed plan: Business or entry Cloud plan.","np":"Eligible non-profits may receive a discount on request.","note":"Matomo Cloud keeps your analytics in Germany. The company is in New Zealand, which the EU and UK treat as having adequate data protection.","conf":"high","src":[["Matomo Pricing (FAQ)","https://matomo.org/pricing/"],["Matomo Cloud Data Processing Agreement","https://matomo.org/matomo-cloud-dpa/"],["Matomo Cloud Privacy Policy","https://matomo.org/matomo-cloud-privacy-policy/"],["What is Two-Factor Authentication?","https://matomo.org/faq/general/faq_27245/"],["Matomo Privacy Policy","https://matomo.org/privacy-policy/"],["matomo-org/matomo LICENSE","https://github.com/matomo-org/matomo/blob/5.x-dev/LICENSE"]]},{"id":"wordpress-com","name":"WordPress.com","job":"Website hosting","k":"Software","w":"Elsewhere","b":"Elsewhere","x":"Partial","o":false,"loc":"US","locs":["US","EU"],"hq":"US","co":"Automattic Inc.","par":null,"parc":null,"store":"US and EU. WordPress.com stores personal data on servers in both the US and the EU and cannot restrict a site to one location. Self-hosted WordPress is different: data lives wherever your web host puts it.","res":"no","plans":"Business plan sites can pick EU West as the primary data centre when hosting features are first activated, but data is still not restricted to the EU.","mfa":"all plans","ai":"yes","aid":"Automattic licenses public site content to third parties, including AI companies, unless you tick 'Prevent third-party sharing' under Settings, Reading. This applies to public content. Assumed plan: Personal or Premium.","np":null,"note":"WordPress.com shares public site content with AI companies unless you tick 'Prevent third-party sharing' in Settings, Reading. If your site is self-hosted WordPress, ask your web host where the server is.","conf":"high","src":[["Your WordPress.com site and the GDPR","https://wordpress.com/support/your-site-and-the-gdpr/"],["Choose your site's primary data center","https://wordpress.com/support/choose-your-sites-primary-data-center/"],["Make your website public","https://wordpress.com/support/privacy-settings/make-your-website-public/"],["Enable two-step authentication","https://wordpress.com/support/security/two-step-authentication/"],["Export your website's content","https://wordpress.com/support/export/"]]},{"id":"surveymonkey","name":"SurveyMonkey","job":"Surveys and forms","k":"Software","w":"Elsewhere","b":"Elsewhere","x":"Partial","o":false,"loc":"US","locs":["US"],"hq":"US","co":"SurveyMonkey Inc. (EU entity: SurveyMonkey Europe UC, Ireland)","par":null,"parc":null,"store":"US by default on AWS. The EU data centre is only available to Enterprise customers.","res":"yes-some-plans","plans":"Enterprise only (per the International Data Center Overview updated 15 April 2025)","mfa":"some plans","ai":"yes","aid":"The privacy notice says SurveyMonkey uses de-identified response data to train its models, and sentiment analysis and other machine learning features are switched on for all accounts and cannot be turned off. No opt-out from de-identified training is described. Assumed plan: Team Advantage or individual Advantage.","np":"Discounts for eligible nonprofits upgrading from a free plan, at SurveyMonkey's discretion and varying by country.","note":"On ordinary plans SurveyMonkey stores your surveys in the US, as the EU data centre is Enterprise only. Free accounts cannot export responses or use two-factor sign-in.","conf":"high","src":[["International Data Center Overview","https://www.surveymonkey.com/mp/legal/international-data-center-overview/"],["SurveyMonkey Privacy Notice","https://www.surveymonkey.com/mp/legal/privacy/"],["SurveyMonkey AI Principles","https://www.surveymonkey.com/product/features/ai-principles/"],["Two-factor Authentication (2FA)","https://help.surveymonkey.com/en/surveymonkey/account/two-factor-authentication/"],["Exporting Survey Results","https://help.surveymonkey.com/en/surveymonkey/analyze/exports/"],["SurveyMonkey for nonprofits","https://www.surveymonkey.com/learn/nonprofit/"]]},{"id":"typeform","name":"Typeform","job":"Surveys and forms","k":"Software","w":"Elsewhere","b":"UK or Europe","x":"Yes","o":false,"loc":"US","locs":["US"],"hq":"ES","co":"TYPEFORM, S.L.","par":null,"parc":null,"store":"US by default. Typeform's main servers are on AWS in Virginia, USA. EU data hosting is only on Enterprise or Growth Custom plans.","res":"yes-some-plans","plans":"Enterprise and Growth Custom","mfa":"all plans","ai":"no","aid":"Typeform's AI FAQ says none of its customers' data is used to train any model. AI-powered insights can be switched off in Admin settings. Assumed plan: Basic or Plus.","np":"NGO discount of 25% forever on monthly plans or 40% forever on yearly plans, by application.","note":"Typeform is a Spanish company but stores your forms in the US unless you are on an Enterprise or Growth Custom plan.","conf":"high","src":[["Security at Typeform","https://help.typeform.com/hc/en-us/articles/360029259552-Security-at-Typeform"],["Integrations available on the EU Data Center","https://help.typeform.com/hc/en-us/articles/52254048333588-Integrations-available-on-the-EU-Data-Center"],["AI with Typeform FAQ","https://help.typeform.com/hc/en-us/articles/33777155298708-AI-with-Typeform-FAQ"],["Export your responses","https://help.typeform.com/hc/en-us/articles/360029253572-Export-your-responses"],["Data portability","https://help.typeform.com/hc/en-us/articles/360029616371-Data-portability"],["Non-profit, NGO, and student discounts at Typeform","https://help.typeform.com/hc/en-us/articles/360039728951-Non-profit-NGO-and-student-discounts-at-Typeform"],["Typeform Privacy Policy","https://www.typeform.com/legal/privacy-policy"]]},{"id":"jotform","name":"Jotform","job":"Online forms","k":"Software","w":"UK, EU or EEA","b":"Elsewhere","x":"Yes","o":false,"loc":"US","locs":["US"],"hq":"US","co":"Jotform Inc.","par":null,"parc":null,"store":"US by default. You can switch to EU storage in account settings (or use eu.jotform.com); form data then moves to Google Cloud servers in Frankfurt, Germany.","res":"yes-on-request","plans":"Offered as an account setting; Jotform does not limit it to a plan on the pages checked","mfa":"all plans","ai":"yes","aid":"Jotform's AI policy says personal data is never used to train its AI, but 'data you include in the forms you create, such as in form fields, may be used to train our AI'. No opt-out is described. Assumed plan: Bronze or Silver.","np":"50% off all annual plans for nonprofit organisations.","note":"Jotform stores forms in the US unless you switch on EU storage in your account settings, so check the Data tab. Its AI policy allows form content to be used for AI training.","conf":"medium","src":[["Jotform Privacy Policy","https://www.jotform.com/privacy/"],["Jotform Security","https://www.jotform.com/security/"],["Jotform EU Safe Forms","https://www.jotform.com/eu-safe-forms/"],["Jotform AI Policy","https://www.jotform.com/ai-policy/"],["Jotform for Nonprofits","https://www.jotform.com/nonprofit/"]]},{"id":"tally","name":"Tally","job":"Online forms","k":"Software","w":"UK, EU or EEA","b":"UK or Europe","x":"Yes","o":false,"loc":"EU","locs":["EU"],"hq":"BE","co":"Tally BV","par":null,"parc":null,"store":"EU. Tally says all form data is encrypted and stored in Europe; the exact country is not stated on the pages checked.","res":"yes-default","plans":"All plans","mfa":"unclear","ai":"no","aid":"No explicit AI training statement found. Tally's DPA says it processes personal data only on the customer's documented instructions and not for other purposes. The privacy notice separately says Tally may use data you provide to improve the tool. Assumed plan: Free or Pro.","np":"30% off Tally Pro forever for new Pro customers that are non-profits.","note":"Tally is a Belgian company and stores form data in the EU. We could not find documentation of two-factor sign-in, so use a strong, unique password.","conf":"medium","src":[["GDPR (Tally Help)","https://tally.so/help/gdpr"],["Privacy Notice - Tally tool","https://tally.so/help/privacy-policy"],["Tally Data Processing Agreement","https://tally.so/help/data-processing-agreement"],["Tally FAQ","https://tally.so/help/faq"],["Tally for non-profit","https://tally.so/help/tally-for-non-profit"]]},{"id":"limesurvey-cloud","name":"LimeSurvey Cloud","job":"Surveys","k":"Software","w":"UK, EU or EEA","b":"UK or Europe","x":"Yes","o":true,"loc":"DE","locs":["DE","FI","GB"],"hq":"DE","co":"LimeSurvey GmbH","par":null,"parc":null,"store":"You choose the server country when creating the instance: Germany, Finland, United Kingdom, USA, Canada or Australia. Data is then stored only in that country.","res":"yes-default","plans":"All Cloud plans, by choosing Germany, Finland or UK at setup","mfa":"all plans","ai":"unclear","aid":"No statement on AI training was found in the privacy notice or product pages checked. Assumed plan: Basic or Expert Cloud plan.","np":"30% discount for charitable organisations on proof of charity status.","note":"When you create your LimeSurvey Cloud site, choose the UK, Germany or Finland as the server location. Two-factor sign-in is a built-in plugin you need to switch on.","conf":"medium","src":[["LimeSurvey Pricing (FAQ)","https://www.limesurvey.org/pricing"],["LimeSurvey Privacy Notice","https://www.limesurvey.org/privacy-notice"],["TwoFactorAdminLogin (LimeSurvey Manual)","https://www.limesurvey.org/manual/TwoFactorAdminLogin"],["Exporting results (LimeSurvey Manual)","https://www.limesurvey.org/manual/Exporting_results"],["LimeSurvey README","https://github.com/LimeSurvey/LimeSurvey"]]}]},{"g":"Design, tasks and passwords","items":[{"id":"canva","name":"Canva","job":"Graphic design","k":"Software","w":"Elsewhere","b":"Elsewhere","x":"Partial","o":false,"loc":"US","locs":["US"],"hq":"OTHER","co":"Canva Pty Ltd","par":null,"parc":null,"store":"US by default. EU storage for designs and media is only offered on Enterprise, Campus and District plans.","res":"yes-some-plans","plans":"Enterprise (and Campus, District education plans); no UK option","mfa":"all plans","ai":"no","aid":"Canva says it does not use content to improve AI unless privacy settings allow it, and the default is off. Individual users can opt in or out in Privacy settings. Teams, Business and Enterprise accounts currently cannot opt in. Canva for Nonprofits runs as a team account.","np":"Canva for Nonprofits: free Canva Pro and team features for up to 50 people for eligible registered charities; extra seats at 50% off Enterprise pricing.","note":"Your designs are stored in the US on the Nonprofits plan, and EU storage is only available on Enterprise. Download important designs as PDF or PPTX regularly, because there is no editable export.","conf":"high","src":[["Set your organization's data residency preference - Canva Help Center","https://www.canva.com/help/data-residency/"],["Canva Trust Center - Privacy","https://www.canva.com/trust/privacy/"],["Canva Privacy Policy","https://www.canva.com/policies/privacy-policy/"],["Statement of Technical and Organisational Measures","https://www.canva.com/policies/technical-and-organisational-measures/"],["Canva for Nonprofits","https://www.canva.com/canva-for-nonprofits/"],["Choose the right download file type for your Canva design","https://www.canva.com/help/download-file-types/"],["Downloading your personal data, uploads, and designs in bulk","https://www.canva.com/help/bulk-download-data-uploads-designs/"],["Canva Help Center - login verification","https://www.canva.com/help/login-verification/"]]},{"id":"trello","name":"Trello","job":"Task boards","k":"Software","w":"Elsewhere","b":"Elsewhere","x":"Partial","o":false,"loc":"US","locs":["US"],"hq":"OTHER","co":"Atlassian (Trello)","par":"Atlassian Corporation","parc":"US","store":"US (AWS data centres). Trello is not listed among Atlassian products that offer data residency.","res":"no","plans":null,"mfa":"all plans","ai":"no","aid":"Atlassian's data contribution scheme, in force from 17 August 2026, uses metadata and in-app data from Free and Standard plans of Jira, Confluence and JSM for AI by default. Atlassian says it does not apply to Trello because Trello has no data contribution settings. Recheck if Trello gets these settings.","np":"Atlassian Social Impact licence: 75% off Trello Standard, Premium and Enterprise for eligible nonprofits.","note":"Trello data is held in the US and there is no option to move it to the UK or EU. Export each board to JSON from time to time, as spreadsheet and full workspace exports need Premium.","conf":"medium","src":[["Trello and GDPR - Our Commitment to Data Privacy","https://support.atlassian.com/trello/docs/trello-and-gdpr-our-commitment-to-data-privacy/"],["Understand data residency - Atlassian Support","https://support.atlassian.com/security-and-access-policies/docs/understand-data-residency/"],["Export data from Trello","https://support.atlassian.com/trello/docs/exporting-data-from-trello/"],["Data Contributions Frequently Asked Questions","https://www.atlassian.com/trust/ai/data-contribution/faqs"],["Data practices built for responsible AI","https://www.atlassian.com/trust/ai/data-contribution"],["Nonprofit Discount Eligibility and Pricing","https://www.atlassian.com/teams/nonprofits/discount-pricing"],["Enable two-factor authentication for your Trello account","https://support.atlassian.com/trello/docs/enabling-two-factor-authentication-for-your-trello-account/"]]},{"id":"asana","name":"Asana","job":"Project management","k":"Software","w":"Elsewhere","b":"Elsewhere","x":"Partial","o":false,"loc":"US","locs":["US"],"hq":"US","co":"Asana, Inc.","par":null,"parc":null,"store":"US (Virginia) by default. Frankfurt storage is a paid add-on on Enterprise and included in Enterprise+.","res":"yes-some-plans","plans":"Enterprise (paid add-on) and Enterprise+; region Frankfurt, Germany; no UK region","mfa":"all plans","ai":"no","aid":"Asana states it does not use customer data for training and its AI partners are contractually barred from doing so. Admins can switch AI features off in the admin console.","np":"Asana for Nonprofits: 50% off Starter and Advanced plans for eligible registered nonprofits, including outside the US.","note":"Asana keeps your data in the US unless you pay for Enterprise with the EU add-on. Only Enterprise plans can force everyone to use two-factor sign-in, so ask staff to turn it on themselves.","conf":"high","src":[["Asana data residency: where your data lives","https://help.asana.com/s/article/data-residency-for-asana?language=en_US"],["Asana Privacy Statement","https://asana.com/terms/privacy-statement"],["Asana AI FAQ","https://help.asana.com/s/article/asana-ai-faq?language=en_US"],["How to import & export projects in Asana","https://help.asana.com/s/article/project-importing-and-exporting?language=en_US"],["Mandatory two-factor authentication in Asana","https://help.asana.com/s/article/mandatory-two-factor-authentication?language=en_US"],["Asana for Nonprofits Discount Program","https://asana.com/industry/nonprofit"]]},{"id":"notion","name":"Notion","job":"Wiki and notes","k":"Software","w":"Elsewhere","b":"Elsewhere","x":"Yes","o":false,"loc":"US","locs":["US"],"hq":"US","co":"Notion Labs, Inc.","par":null,"parc":null,"store":"US by default. Enterprise customers can choose Frankfurt (EU) for workspace content at no extra cost.","res":"yes-some-plans","plans":"Enterprise only; EU region Frankfurt; no UK region; Notion Mail and Calendar excluded","mfa":"all plans","ai":"no","aid":"Notion says it does not use workspace data to train models by default. Sharing is only through the opt-in AI LEAP programme. AI subprocessors are contractually barred from training on customer data.","np":"50% off the Business plan for eligible nonprofits worldwide (up to three workspaces), after verification.","note":"On non-Enterprise plans your Notion content is stored in the US. Two-step sign-in is available to everyone but admins cannot enforce it for members, so ask each person to switch it on.","conf":"high","src":[["Data residency for Notion","https://www.notion.com/help/data-residency"],["Export your content - Notion Help","https://www.notion.com/help/export-your-content"],["Notion's commitment to AI safety","https://www.notion.com/help/ai-safety"],["Two-step verification in Notion","https://www.notion.com/help/two-step-verification"],["Notion for nonprofits","https://www.notion.com/nonprofits"],["Notion (productivity software) - Wikipedia","https://en.wikipedia.org/wiki/Notion_(productivity_software)"]]},{"id":"airtable","name":"Airtable","job":"Shared databases","k":"Software","w":"Elsewhere","b":"Elsewhere","x":"Partial","o":false,"loc":"US","locs":["US"],"hq":"US","co":"Formagrid Inc (Airtable)","par":null,"parc":null,"store":"US by default. EU storage is only available on Enterprise Scale, and some metadata and login data stay in the US even then.","res":"yes-some-plans","plans":"Enterprise Scale only; EU region; no UK region","mfa":"all plans","ai":"no","aid":"Airtable's AI Terms say it will not use or let AI providers use customer data to train generative AI models. On Free, Team and similar plans, providers may keep inputs for up to 30 days for safety checks.","np":"50% off the Team plan for eligible registered nonprofits, including outside the US; monthly billing only; not for Business or Enterprise Scale.","note":"Airtable stores your bases in the US on the Team plan. Leaving is hard because export is one table at a time as CSV, so keep regular copies and save attachments separately.","conf":"high","src":[["Data residency at Airtable","https://support.airtable.com/docs/data-residency-at-airtable"],["Airtable Privacy Policy","https://www.airtable.com/company/privacy"],["Airtable AI Terms","https://www.airtable.com/company/ai-terms"],["Creating and managing Airtable bases","https://support.airtable.com/articles/7403739720-creating-and-managing-airtable-bases"],["Airtable export: CSV, Excel, backups and base limits","https://www.breeze.pm/articles/export-from-airtable"],["Airtable Trust & Security","https://www.airtable.com/company/trust-and-security"],["Applying for non-profit, education, and student Airtable plans","https://support.airtable.com/docs/nonprofit-and-educational-plans-faqs"]]},{"id":"monday-com","name":"monday.com","job":"Work management","k":"Software","w":"Don't know","b":"Elsewhere","x":"Partial","o":false,"loc":"","locs":["DE"],"hq":"OTHER","co":"monday.com Ltd.","par":null,"parc":null,"store":"Set by where the first user is when the account opens. Accounts opened from the EU on Standard, Pro or Enterprise go to the EU region (Germany); the UK is not named, and most others default to the US.","res":"yes-some-plans","plans":"Standard and Pro accounts created on or after 23 January 2023, and Enterprise; not Free or Basic","mfa":"all plans","ai":"no","aid":"monday.com says it does not use customer data to train AI models and bars its AI providers from doing so. It may access data temporarily, up to 60 days, to improve services and detect abuse; an admin can opt out by emailing ai-support@monday.com.","np":"10 free seats on the Pro plan for eligible nonprofits, 70% off extra seats and Pro add-ons, 33% off Enterprise; UK Community Interest Companies are excluded.","note":"Check Administration, then Profile, to see which region your account is stored in, because it is fixed when the account is created and cannot be moved later. UK charities should not assume EU storage.","conf":"medium","src":[["Data residency: where your data is stored","https://support.monday.com/hc/en-us/articles/4404392703250-Data-residency"],["monday.com Trust Center - Privacy","https://monday.com/trustcenter/privacy/overview"],["How to export your entire account's data","https://support.monday.com/hc/en-us/articles/360002543719-How-to-export-your-entire-account-s-data"],["Two-Factor Authentication","https://support.monday.com/hc/en-us/articles/360000787745-Two-Factor-Authentication"],["AI FAQs","https://support.monday.com/hc/en-us/articles/23227256685842-AI-FAQs"],["monday.com for nonprofits","https://support.monday.com/hc/en-us/articles/115005321269-monday-com-for-nonprofits"]]},{"id":"openproject-cloud","name":"OpenProject (cloud)","job":"Project management","k":"Software","w":"UK, EU or EEA","b":"UK or Europe","x":"Partial","o":true,"loc":"EU","locs":["EU"],"hq":"DE","co":"OpenProject GmbH","par":null,"parc":null,"store":"EU. The standard cloud runs on Amazon Web Services with all services in Europe; hosting on EU-owned Scaleway is available on request.","res":"yes-default","plans":"All cloud plans","mfa":"all plans","ai":"not-applicable","aid":"OpenProject does not run its own AI model. AI use is through its MCP server with a client and model the organisation chooses. No statement on training was found in its privacy pages.","np":"Special rates for NGOs and educational institutions on request from sales; no published discount.","note":"Your data stays in the EU, but on a US-owned cloud provider unless you ask for EU-owned Scaleway hosting. Check backup size, as attachments over 1 GB are left out of self-service backups.","conf":"medium","src":[["GDPR - OpenProject Enterprise cloud guide","https://www.openproject.org/docs/enterprise-guide/enterprise-cloud-guide/gdpr-compliance/"],["Security and privacy - OpenProject","https://www.openproject.org/security-and-privacy/"],["OpenProject pricing","https://www.openproject.org/pricing/"],["Backups - OpenProject Enterprise cloud guide","https://www.openproject.org/docs/enterprise-guide/enterprise-cloud-guide/backups/"],["Enterprise cloud FAQ","https://www.openproject.org/docs/enterprise-guide/enterprise-cloud-guide/enterprise-cloud-faq/"],["Two-factor authentication (2FA) - OpenProject","https://www.openproject.org/docs/system-admin-guide/authentication/two-factor-authentication/"],["OpenProject AI","https://www.openproject.org/ai/"]]},{"id":"lastpass","name":"LastPass","job":"Password manager","k":"Software","w":"Elsewhere","b":"Elsewhere","x":"Partial","o":false,"loc":"US","locs":["US"],"hq":"US","co":"LastPass US LP","par":"Francisco Partners and Elliott Investment Management (private equity owners)","parc":"US","store":"US by default. LastPass also runs vault storage in Europe (Ireland, Germany, UK), used when elected at account creation.","res":"yes-on-request","plans":"Not stated by plan; region is elected when the account is created","mfa":"all plans","ai":"not-applicable","aid":"Vault contents are encrypted on the device and LastPass says it cannot read them. The privacy policy does not mention AI training for account or usage data.","np":null,"note":"Vaults are stored in the US unless Europe was chosen when the account was set up, so ask LastPass which region yours uses. LastPass had a major breach in 2022 that led to a UK ICO fine in 2025.","conf":"medium","src":[["LastPass Sub-Processors (April 2025)","https://www.lastpass.com/-/media/50dd502f16c34e99ad3ba7ea031d55ab.pdf"],["LastPass Technical and Organizational Measures (January 2025)","https://www.lastpass.com/-/media/175854c49fcb489baeaa87e78579e28f.pdf"],["LastPass Privacy Policy","https://www.lastpass.com/legal-center/privacy-policy"],["LastPass Pricing","https://www.lastpass.com/pricing"],["Import from LastPass - Bitwarden Help","https://bitwarden.com/help/import-from-lastpass/"],["LastPass - Wikipedia","https://en.wikipedia.org/wiki/LastPass"]]},{"id":"1password","name":"1Password","job":"Password manager","k":"Software","w":"UK, EU or EEA","b":"Elsewhere","x":"Yes","o":false,"loc":"EU","locs":["EU"],"hq":"OTHER","co":"AgileBits Inc. (1Password)","par":null,"parc":null,"store":"Depends on the sign-up site: accounts made on 1Password.eu are hosted in the EU, 1Password.com in the US. Data is never moved automatically between regions.","res":"yes-on-request","plans":"All plans; choose 1Password.eu when creating the account","mfa":"all plans","ai":"not-applicable","aid":"Vault items are end-to-end encrypted and 1Password staff cannot read them. The privacy notice does not describe using customer data to train AI.","np":"Discounts for eligible nonprofits through the sales team; no published rate.","note":"Make sure your account address ends in 1Password.eu if you want EU hosting, because an account made on 1Password.com is in the US and cannot be moved without starting again.","conf":"high","src":[["1Password in your region","https://support.1password.com/regions/"],["1Password Privacy Notice","https://1password.com/legal/privacy"],["Export your data from 1Password","https://support.1password.com/export/"],["Use two-factor authentication for your 1Password account","https://support.1password.com/two-factor-authentication/"],["About the 1Password security model","https://support.1password.com/1password-security/"],["1Password Business pricing","https://1password.com/pricing/business"]]},{"id":"bitwarden","name":"Bitwarden","job":"Password manager","k":"Software","w":"UK, EU or EEA","b":"Elsewhere","x":"Partial","o":true,"loc":"EU","locs":["EU"],"hq":"US","co":"Bitwarden, Inc.","par":null,"parc":null,"store":"You pick US or EU in the server drop-down when you create the account or organisation. EU data sits in Microsoft Azure in the EU.","res":"yes-on-request","plans":"All cloud plans; choose the EU server at sign-up","mfa":"all plans","ai":"not-applicable","aid":"Vault data is encrypted on the device before it reaches Bitwarden's servers, so it cannot be read for training. No AI training use is described.","np":null,"note":"Choose the EU server when you sign up, because moving from US to EU later means exporting and re-importing everything. Most of the code is open source under GPL and AGPL, with some business features under Bitwarden's own licence.","conf":"high","src":[["Server Regions - Bitwarden","https://bitwarden.com/help/server-geographies/"],["Data Storage - Bitwarden","https://bitwarden.com/help/data-storage/"],["Export Vault Data - Bitwarden","https://bitwarden.com/help/export-your-data/"],["Two-step Login Methods - Bitwarden","https://bitwarden.com/help/setup-two-step-login/"],["bitwarden/server LICENSE","https://github.com/bitwarden/server/blob/main/LICENSE.txt"],["Bitwarden Privacy Policy","https://bitwarden.com/privacy/"]]},{"id":"proton-pass","name":"Proton Pass","job":"Password manager","k":"Software","w":"Don't know","b":"UK or Europe","x":"Yes","o":false,"loc":"","locs":["CH","DE","NO"],"hq":"CH","co":"Proton AG","par":"Proton Foundation","parc":"CH","store":"Proton-owned servers located only in Switzerland, Germany or Norway. Proton does not say which country a given account uses and there is no customer choice.","res":"unclear","plans":null,"mfa":"all plans","ai":"not-applicable","aid":"Proton Pass data, including metadata, is end-to-end encrypted and Proton says it cannot decrypt it.","np":"Discounted rates for nonprofits on Proton Pass and other Proton services; rate not published.","note":"Your vault may be stored in Switzerland or Norway rather than the EU, although Switzerland and Norway have strong data protection laws. Business plans let admins require two-factor sign-in for everyone.","conf":"medium","src":[["Proton Pass Privacy Policy","https://proton.me/pass/privacy-policy"],["How to enforce 2FA for users","https://proton.me/support/pass-business-enforce-2fa"],["How to export passwords from Proton Pass","https://proton.me/support/pass-export"],["Password manager for nonprofits - Proton Pass","https://proton.me/business/pass/password-manager-for-nonprofits"],["Proton Pass security","https://proton.me/pass/security"],["Proton non-profit foundation","https://proton.me/blog/proton-non-profit-foundation"]]},{"id":"keepassxc","name":"KeePassXC","job":"Password manager","k":"Software","w":"Don't know","b":"UK or Europe","x":"Yes","o":true,"loc":"","locs":[],"hq":"DE","co":"KeePassXC Team (volunteer open-source project)","par":null,"parc":null,"store":"On the user's own device, in an encrypted .kdbx file. It only goes elsewhere if you put the file in a cloud folder you choose.","res":"unclear","plans":null,"mfa":"all plans","ai":"not-applicable","aid":"The app runs locally and the project says no stored data is ever sent to it or third parties.","np":"Free for everyone.","note":"KeePassXC keeps passwords in a file on your own computer, so data location is wherever you save or sync that file. Decide where it is stored and backed up, and who holds the master password.","conf":"high","src":[["KeePassXC Password Manager","https://keepassxc.org/"],["KeePassXC User Guide","https://keepassxc.org/docs/KeePassXC_UserGuide"],["KeePassXC Privacy Policy","https://keepassxc.org/privacy/"],["KeePassXC Team","https://keepassxc.org/team"]]}]}];
